"""
ADHD Focus Bot v5
- Персонализация: имя + пол
- Русский язык по умолчанию
- Утро: разминка, фокус, задачи A/B/C, free writing, благодарность, внутренний ребёнок
- Вечер: достижения, похвала, highlights, планы A/B/C, AI-анализ дня
- Навыки СДВГ из тренинга (ежедневный совет)
- AI: коуч + утренняя мотивация + вечерний анализ
- Уведомления: 9:00 и 21:00 по Тбилиси (UTC+4)
"""

import os, json, sqlite3, asyncio, random, threading, time, hashlib, re
from datetime import datetime, date, timedelta
import pytz
from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup, LabeledPrice
from telegram.ext import (
    Application, CommandHandler, CallbackQueryHandler,
    MessageHandler, ConversationHandler, filters, ContextTypes,
    PicklePersistence, PreCheckoutQueryHandler, ApplicationHandlerStop, TypeHandler
)
from apscheduler.schedulers.asyncio import AsyncIOScheduler

# ── CONFIG ─────────────────────────────────────────────────────────────────
BOT_TOKEN     = os.getenv("BOT_TOKEN", "YOUR_BOT_TOKEN")
ANTHROPIC_KEY = os.getenv("ANTHROPIC_KEY", "")
# Укажи свой Telegram ID для уведомлений (узнай через @userinfobot)
NOTIFY_USER_ID = int(os.getenv("NOTIFY_USER_ID", "0"))
# Таймзона пользователя — время уведомлений в настройках бота задаётся в этой зоне
# Примеры: "Asia/Tbilisi", "Europe/Moscow", "Europe/Berlin", "UTC"
USER_TIMEZONE = os.getenv("USER_TIMEZONE", "Asia/Tbilisi")
# Путь к SQLite-базе — укажи путь на смонтированном volume (например /data/adhd.db),
# иначе данные будут теряться при каждом передеплое
DB_PATH = os.getenv("DB_PATH", "adhd.db")

# ── ДОСТУП / ПОДПИСКА ──────────────────────────────────────────────────────
# Общий рубильник платного доступа. Включён явным решением (не флагом
# окружения) — пользователи с истёкшим пробным периодом видят пейволл.
ACCESS_GATE_ENABLED = True
TRIAL_DAYS = 7  # бесплатный период с момента регистрации (created_at) + promo_extra_days
STARS_SUBSCRIPTION_DAYS = 30
STARS_PRICE_MONTHLY = 150  # 150 ⭐ Stars/месяц
# Статичные анимации-инструменты (не данные пользователя, один и тот же файл
# для всех) — путь считаем от расположения самого файла, а не от cwd, чтобы
# не зависеть от того, откуда запущен процесс.
ANIMATIONS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "assets", "animations")
# ctx.user_data и состояния диалогов (онбординг/утро/вечер) раньше жили только
# в памяти процесса — рестарт (в т.ч. от вотчдога при зависании) стирал любой
# незаконченный диалог или введённый-но-не-отправленный ответ. Файл кладём
# рядом с БД — если DB_PATH указывает на смонтированный volume, персистентность
# автоматически переживает передеплой вместе с базой, без отдельной настройки.
PERSISTENCE_PATH = os.getenv(
    "PERSISTENCE_PATH",
    os.path.join(os.path.dirname(DB_PATH) or ".", "bot_persistence.pickle")
)

# Автосброс зависших диалогов (утро/вечер/онбординг). Без таймаута человек,
# бросивший шаг с вводом текста на середине, застревает в нём навсегда —
# любое следующее сообщение (даже не связанное, например фидбек) будет
# по ошибке принято за ответ на давно забытый вопрос.
CONV_TIMEOUT_SHORT = 600   # 10 минут — онбординг (имя/пол)
CONV_TIMEOUT_LONG  = 1800  # 30 минут — утренний и вечерний блок

# Утренний и вечерний ConversationHandler — независимые друг от друга и оба
# зарегистрированы в одной группе, поэтому если один из них "застрял" на
# текстовом шаге (пользователь начал, но не закончил), он молча перехватит
# любое следующее текстовое сообщение — даже предназначенное для другого
# потока. Ссылки заполняются в main() и используются morning_start/
# evening_start, чтобы сбрасывать "застрявшее" состояние друг друга при
# явном переключении между потоками.
_morning_conv = None
_evening_conv = None

# ── CONVERSATION STATES ────────────────────────────────────────────────────
(ONBOARD_NAME, ONBOARD_GENDER,
 M_EXERCISE, M_FOCUS, M_B1, M_B2, M_C1, M_C2, M_C3,
 M_WRITING, M_GRATITUDE, M_CHILD,
 E_TASKS_DONE, E_ACH, E_PRAISE, E_HIGHLIGHTS, E_SELFCARE, E_ENERGY,
 E_A, E_B1, E_B2, E_C1, E_C2, E_C3) = range(24)

