# ── DATABASE ───────────────────────────────────────────────────────────────
def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    # WAL персистится в самом файле БД, достаточно включить один раз —
    # без него параллельная запись (тик планировщика раз в минуту против
    # обработчика нажатой кнопки) рискует получить "database is locked".
    c.execute("PRAGMA journal_mode=WAL")
    c.execute("""CREATE TABLE IF NOT EXISTS users (
        user_id INTEGER PRIMARY KEY,
        name TEXT DEFAULT '',
        gender TEXT DEFAULT 'M',
        focus TEXT DEFAULT '',
        streak TEXT DEFAULT '[]',
        last_skill_date TEXT DEFAULT '',
        buddy_name TEXT DEFAULT '',
        notif_morning TEXT DEFAULT '09:00',
        notif_midday TEXT DEFAULT '13:00',
        notif_evening TEXT DEFAULT '21:00',
        notif_enabled INTEGER DEFAULT 1
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS diary (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER, date TEXT, block TEXT, data TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS tasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER, text TEXT,
        priority TEXT DEFAULT 'C',
        done INTEGER DEFAULT 0,
        created TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS reminders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER, text TEXT, remind_at TEXT, recur TEXT DEFAULT '', created TEXT
    )""")
    try:
        c.execute("ALTER TABLE reminders ADD COLUMN recur TEXT DEFAULT ''")
    except Exception:
        pass
    c.execute("""CREATE TABLE IF NOT EXISTS feedback (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER, text TEXT, created TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS research (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER, day INTEGER, question TEXT,
        answer TEXT, created TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS promo_codes (
        code TEXT PRIMARY KEY,
        days INTEGER DEFAULT 30,
        max_uses INTEGER DEFAULT 1,
        uses INTEGER DEFAULT 0,
        created TEXT,
        label TEXT DEFAULT ''
    )""")
    try:
        c.execute("ALTER TABLE promo_codes ADD COLUMN label TEXT DEFAULT ''")
    except Exception:
        pass
    c.execute("""CREATE TABLE IF NOT EXISTS promo_redemptions (
        user_id INTEGER, code TEXT, redeemed TEXT,
        PRIMARY KEY (user_id, code)
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS payments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER, stars INTEGER, days INTEGER,
        charge_id TEXT, created TEXT
    )""")

    # Migrate existing DB - add columns if missing
    for col, default in [
        ("timezone", f"'{USER_TIMEZONE}'"),
        ("buddy_name", "''"),
        ("notif_morning", "'09:00'"),
        ("notif_midday", "'13:00'"),
        ("notif_evening", "'21:00'"),
        ("notif_enabled", "1"),
        ("notif_morning_on", "1"),
        ("notif_midday_on",  "1"),
        ("notif_evening_on", "1"),
        ("beacon_enabled", "0"),
        ("beacon_interval", "2"),
        ("beacon_last_sent", "''"),
        ("beacon_start", "'09:00'"),
        ("beacon_end", "'21:00'"),
        ("morning_sent_date", "''"),
        ("midday_sent_date", "''"),
        ("evening_sent_date", "''"),
        ("weekly_report_sent_date", "''"),
        ("morning_reminder_sent_date", "''"),
        ("focus_active", "0"),
        ("focus_end_time", "''"),
        ("focus_duration", "0"),
        ("focus_minutes_today", "0"),
        ("focus_date", "''"),
        ("city", "''"),
        ("created_at", f"'{date.today().isoformat()}'"),
        ("research_done", "''"),
        ("research_awaiting", "0"),
        ("resume_check_due", "''"),
        ("struggles", "''"),
        ("pinned_msg_id", "''"),
        ("morning_filled_at", "''"),
        ("onboard_explained", "'0'"),
        ("daily_skill_override", "''"),
        ("disabled_fields", "''"),
        ("skip_streaks", "''"),
        ("beacon_types", "''"),
        ("beacon_rotation_idx", "'0'"),
        ("promo_extra_days", "0"),
        ("subscription_until", "''"),
        ("skill_beacon_enabled", "0"),
        ("skill_beacon_mode", "'interval'"),
        ("skill_beacon_interval", "60"),
        ("skill_beacon_daily_count", "3"),
        ("skill_beacon_last_sent", "''"),
        ("streak_hidden", "0"),
        ("work_start_time", "''"),
        ("work_start_date", "''"),
        ("work_start_sent_date", "''"),
    ]:
        try:
            c.execute(f"ALTER TABLE users ADD COLUMN {col} TEXT DEFAULT {default}")
        except Exception:
            pass
    conn.commit(); conn.close()

def get_user(uid):
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute("SELECT * FROM users WHERE user_id=?", (uid,))
    row = c.fetchone()
    if not row:
        # created_at НЕ оставляем на дефолт колонки — SQLite "запекает" DEFAULT
        # в момент ALTER TABLE как фиксированный литерал, а не выражение,
        # переоцениваемое на каждый INSERT. Раз колонка добавлена миграцией
        # один раз, все новые пользователи получали бы одну и ту же
        # "дату регистрации" — что ломает расчёт cadence исследовательских
        # вопросов (день 3/7/14/30). date.today() тоже наивная — на момент
        # первого /start таймзона пользователя ещё не известна (задаётся
        # позже в онбординге), поэтому берём дефолтный пояс бота.
        c.execute(
            "INSERT INTO users(user_id, created_at) VALUES(?,?)",
            (uid, datetime.now(pytz.timezone(USER_TIMEZONE)).date().isoformat())
        )
        conn.commit()
        c.execute("SELECT * FROM users WHERE user_id=?", (uid,))
        row = c.fetchone()
    result = dict(row)
    conn.close()
    return result

def update_user(uid, **kwargs):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    for k, v in kwargs.items():
        c.execute(f"UPDATE users SET {k}=? WHERE user_id=?", (v, uid))
    conn.commit(); conn.close()

# ── ДОСТУП / ПОДПИСКА ────────────────────────────────────────────────────
def get_access_status(user):
    """trial / subscribed / expired. Владелец бота (NOTIFY_USER_ID) всегда
    subscribed — иначе легко случайно выпилить себе доступ во время теста."""
    if NOTIFY_USER_ID and int(user.get("user_id") or 0) == NOTIFY_USER_ID:
        return "subscribed"
    today = datetime.now(get_user_tz(user)).date()
    sub_until = user.get("subscription_until") or ""
    if sub_until:
        try:
            if date.fromisoformat(sub_until[:10]) >= today:
                return "subscribed"
        except Exception:
            pass
    created = (user.get("created_at") or today.isoformat())[:10]
    try:
        created_date = date.fromisoformat(created)
    except Exception:
        created_date = today
    extra_days = int(user.get("promo_extra_days") or 0)
    trial_end = created_date + timedelta(days=TRIAL_DAYS + extra_days)
    return "trial" if today <= trial_end else "expired"

def get_trial_days_left(user):
    today = datetime.now(get_user_tz(user)).date()
    created = (user.get("created_at") or today.isoformat())[:10]
    try:
        created_date = date.fromisoformat(created)
    except Exception:
        created_date = today
    extra_days = int(user.get("promo_extra_days") or 0)
    trial_end = created_date + timedelta(days=TRIAL_DAYS + extra_days)
    return max(0, (trial_end - today).days)

def create_promo_code(code, days, max_uses, label=""):
    """max_uses=0 значит без ограничения — так делаются личные коды
    блогеров, которые видит вся их аудитория, а не один человек."""
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute(
        "INSERT OR REPLACE INTO promo_codes(code, days, max_uses, uses, created, label) VALUES(?,?,?,?,?,?)",
        (code, days, max_uses, 0, datetime.now().isoformat(), label)
    )
    conn.commit(); conn.close()

def promo_code_exists(code):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    row = c.execute("SELECT 1 FROM promo_codes WHERE code=?", (code,)).fetchone()
    conn.close()
    return row is not None

def list_promo_codes():
    """Список всех кодов с числом активаций — чтобы видеть, сколько
    пользователей пришло через каждый (в т.ч. через блогерские)."""
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    rows = c.execute(
        "SELECT code, label, days, uses, max_uses, created FROM promo_codes ORDER BY uses DESC, created DESC"
    ).fetchall()
    conn.close()
    return rows

def _slugify_promo_code(name):
    s = re.sub(r"[^0-9A-Za-zА-Яа-яЁё]", "", name).upper()
    return s[:20] or "PROMO"

def redeem_promo_code(uid, code):
    """Возвращает (ok: bool, message: str). Промокод продлевает пробный
    период (promo_extra_days), а не даёт постоянный доступ — это осознанное
    решение: подарок должен заканчиваться, иначе это не пробный период."""
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    row = c.execute("SELECT days, max_uses, uses FROM promo_codes WHERE code=?", (code,)).fetchone()
    if not row:
        conn.close()
        return False, "Такого промокода нет — проверь, правильно ли ввёл(а)."
    days, max_uses, uses = row
    already = c.execute(
        "SELECT 1 FROM promo_redemptions WHERE user_id=? AND code=?", (uid, code)
    ).fetchone()
    if already:
        conn.close()
        return False, "Этот промокод уже использован тобой раньше."
    if max_uses > 0 and uses >= max_uses:
        conn.close()
        return False, "У этого промокода закончились активации."
    c.execute("UPDATE promo_codes SET uses = uses + 1 WHERE code=?", (code,))
    c.execute(
        "INSERT INTO promo_redemptions(user_id, code, redeemed) VALUES(?,?,?)",
        (uid, code, datetime.now().isoformat())
    )
    conn.commit(); conn.close()
    user = get_user(uid)
    new_extra = int(user.get("promo_extra_days") or 0) + days
    update_user(uid, promo_extra_days=new_extra)
    return True, f"Промокод принят — пробный период продлён на {days} дн. 🎉"

def grant_access_days(uid, days):
    """Прямая выдача доступа конкретному аккаунту, без промокода — для
    случаев когда уже точно знаешь, кому дать (см. /grant и кнопку
    «🎁 +30» в /users). Продлевает subscription_until от максимума из
    "сегодня" и уже имеющейся подписки — так же, как реальная оплата
    (successful_payment_callback). Раньше это добавлялось к
    promo_extra_days, который отсчитывается от даты РЕГИСТРАЦИИ — для
    аккаунта, чей триал истёк давно, это не давало вообще никакого
    доступа прямо сейчас, хотя и админу, и пользователю бот отвечал, что
    доступ продлён."""
    user = get_user(uid)
    today = datetime.now(get_user_tz(user)).date()
    current_until = user.get("subscription_until") or ""
    try:
        base = max(today, date.fromisoformat(current_until[:10]))
    except Exception:
        base = today
    update_user(uid, subscription_until=(base + timedelta(days=days)).isoformat())

def save_payment(uid, stars, days, charge_id):
    """Отдельный лог реальных оплат Stars — источник для /admin ("сколько
    людей заплатило", "сколько всего Stars"), а не просто текущий статус
    subscription_until (который не отличает "заплатил и подписка ещё
    активна" от "заплатил, но подписка уже закончилась")."""
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute(
        "INSERT INTO payments(user_id, stars, days, charge_id, created) VALUES(?,?,?,?,?)",
        (uid, stars, days, charge_id, datetime.now().isoformat())
    )
    conn.commit(); conn.close()

def save_diary(uid, block, data, for_date=None):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    d = for_date or date.today().isoformat()
    c.execute("DELETE FROM diary WHERE user_id=? AND date=? AND block=?", (uid, d, block))
    c.execute("INSERT INTO diary(user_id,date,block,data) VALUES(?,?,?,?)",
              (uid, d, block, json.dumps(data, ensure_ascii=False)))
    conn.commit(); conn.close()

def has_any_diary_ever(uid):
    """Заполнял(а) ли пользователь дневник хоть раз — используется, чтобы не
    показывать в самый первый вечерний прогон чек-лист техник (SELFCARE_ITEMS),
    которые новичок ещё не видел и не понимает."""
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT 1 FROM diary WHERE user_id=? LIMIT 1", (uid,))
    row = c.fetchone()
    conn.close()
    return row is not None

