def add_reminder(uid, text, remind_at_key, recur=""):
    """remind_at_key — naive 'YYYY-MM-DDTHH:MM:SS' в локальном времени
    пользователя (не UTC) — так же, как day_key/now сравниваются везде
    в check_notifications, лексикографическое сравнение строк работает
    как сравнение времени благодаря фиксированной ширине полей.

    recur — "" (разовое), "daily" (каждый день) или "weekly" (раз в
    неделю, в тот же день недели, что и remind_at) — конкретный день
    недели отдельно не хранится, он и так закодирован в remind_at."""
    conn = sqlite3.connect(DB_PATH)
    conn.execute("INSERT INTO reminders(user_id, text, remind_at, recur, created) VALUES (?, ?, ?, ?, ?)",
                 (uid, text, remind_at_key, recur, datetime.now().isoformat()))
    conn.commit(); conn.close()

def get_reminders(uid):
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    rows = conn.execute("SELECT id, text, remind_at, recur FROM reminders WHERE user_id=? ORDER BY remind_at", (uid,)).fetchall()
    conn.close()
    return [dict(r) for r in rows]

def cancel_reminder(uid, rem_id):
    conn = sqlite3.connect(DB_PATH)
    conn.execute("DELETE FROM reminders WHERE id=? AND user_id=?", (rem_id, uid))
    conn.commit(); conn.close()

def update_reminder(uid, rem_id, text, remind_at_key, recur=""):
    conn = sqlite3.connect(DB_PATH)
    conn.execute("UPDATE reminders SET text=?, remind_at=?, recur=? WHERE id=? AND user_id=?",
                 (text, remind_at_key, recur, rem_id, uid))
    conn.commit(); conn.close()

def reschedule_reminder(uid, rem_id, remind_at_key):
    """Переносит повторяющееся напоминание на следующее срабатывание —
    в отличие от cancel_reminder, запись не удаляется."""
    conn = sqlite3.connect(DB_PATH)
    conn.execute("UPDATE reminders SET remind_at=? WHERE id=? AND user_id=?",
                 (remind_at_key, rem_id, uid))
    conn.commit(); conn.close()

def get_reminder(uid, rem_id):
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    row = conn.execute("SELECT id, text, remind_at, recur FROM reminders WHERE id=? AND user_id=?", (rem_id, uid)).fetchone()
    conn.close()
    return dict(row) if row else None

def get_due_reminders(uid, now_key):
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    rows = conn.execute("SELECT id, text, remind_at, recur FROM reminders WHERE user_id=? AND remind_at<=?", (uid, now_key)).fetchall()
    conn.close()
    return [dict(r) for r in rows]

def next_recur_time(remind_at_key, recur, now_dt):
    """Следующее срабатывание повторяющегося напоминания, строго позже
    now_dt — если бот был офлайн и пропустил несколько срабатываний
    подряд, отматывает сразу до ближайшего будущего момента, а не
    присылает пачку пропущенных напоминаний одно за другим."""
    step = timedelta(days=1) if recur == "daily" else timedelta(days=7)
    when = datetime.fromisoformat(remind_at_key)
    while when <= now_dt.replace(tzinfo=None):
        when += step
    return when.strftime("%Y-%m-%dT%H:%M:%S")

_WEEKDAY_RECUR_LABELS = ["понедельникам", "вторникам", "средам", "четвергам", "пятницам", "субботам", "воскресеньям"]

def recur_label(remind_at_key, recur):
    """Короткое описание повтора для сообщений — '' для разового."""
    if recur == "daily":
        return "каждый день"
    if recur == "weekly":
        try:
            wd = date.fromisoformat(remind_at_key[:10]).weekday()
            return f"по {_WEEKDAY_RECUR_LABELS[wd]}"
        except Exception:
            return "каждую неделю"
    return ""

def get_latest_evening_plan(uid):
    """Вчерашний вечерний дневник для переноса плана в утро.

    Помимо "строго вчера" проверяем ещё и "сегодня": если человек заполнял
    вечерний блок уже за полночь (по своему времени), запись физически
    попадает в бакет "сегодня", а не "вчера" — и обычный "вчера"-запрос её
    не находит, план молча пропадает. Берём непустую запись, отдавая
    приоритет более свежей (сегодняшней), если она есть.
    """
    today_date = datetime.now(get_user_tz(get_user(uid))).date()
    today = get_diary(uid, "evening", today_date.isoformat())
    if today.get("e_a"):
        return today
    yesterday = get_diary(uid, "evening", (today_date - timedelta(days=1)).isoformat())
    return yesterday

def save_feedback(uid, text):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("INSERT INTO feedback(user_id,text,created) VALUES(?,?,?)",
              (uid, text, datetime.now().isoformat()))
    conn.commit(); conn.close()

def evening_day(tz) -> date:
    """Логический день для вечернего отчёта и стрика — до 4 утра ещё
    считается вчерашним днём, чтобы у тех, кто закрывает день за полночь
    (частый случай при СДВГ), отчёт и стрик не съезжали на новый день
    и не показывали 0 сразу после полуночи."""
    now = datetime.now(tz)
    d = now.date()
    if now.hour < 4:
        d -= timedelta(days=1)
    return d

def add_streak(uid, for_date=None):
    user = get_user(uid)
    streak = json.loads(user["streak"])
    today = for_date or evening_day(get_user_tz(user)).isoformat()
    if today not in streak:
        streak.append(today)
        update_user(uid, streak=json.dumps(streak))

def calc_streak(uid):
    user = get_user(uid)
    tz = get_user_tz(user)
    today = evening_day(tz)
    streak = sorted(set(json.loads(user["streak"])), reverse=True)
    if not streak: return 0
    count = 0
    for i, d in enumerate(streak):
        if (today - date.fromisoformat(d)).days == i: count += 1
        else: break
    return count

# ── TIMEZONE HELPERS ───────────────────────────────────────────────────────
def get_user_tz(user) -> pytz.BaseTzInfo:
    """Таймзона пользователя — из его профиля, иначе дефолт."""
    tz_name = user.get("timezone") or USER_TIMEZONE
    try:
        return pytz.timezone(tz_name)
    except Exception:
        return pytz.timezone(USER_TIMEZONE)

def _sync_tz_lookup(city: str):
    """Синхронный геокодинг города → название таймзоны. Запускать через run_in_executor."""
    try:
        from geopy.geocoders import Nominatim
        from timezonefinder import TimezoneFinder
        geolocator = Nominatim(user_agent="adhd_focus_bot", timeout=5)
        location = geolocator.geocode(city, language="en")
        if not location:
            return None
        tf = TimezoneFinder()
        return tf.timezone_at(lat=location.latitude, lng=location.longitude)
    except Exception as e:
        print(f"Timezone lookup error for '{city}': {e}")
        return None

async def get_timezone_from_city(city: str):
    """Асинхронная обёртка над геокодингом."""
    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(None, _sync_tz_lookup, city)

# ── HELPERS ────────────────────────────────────────────────────────────────
def g(gender, male, female):
    """Вернуть нужную форму слова в зависимости от пола."""
    if gender == 'F': return female
    if gender == 'N': return f"{male}(а)"
    return male

# Пары "неправильных" форм, которые не подчиняются простому правилу
# склеивания суффикса (беглая гласная, чередование ё/е) — заменяются
# явно, до общей regex-замены в personalize().
_PERSONALIZE_IRREGULAR = {
    "должен(а)":            ("должен", "должна"),
    "отвлёкся(ась)":        ("отвлёкся", "отвлеклась"),
    "вернулся(ась)":        ("вернулся", "вернулась"),
    "провёл(а)":            ("провёл", "провела"),
    "благодарен(а)":        ("благодарен", "благодарна"),
    "несовершенным(ой)":    ("несовершенным", "несовершенной"),
}

def personalize(text, gender):
    """Заменяет гендерные плейсхолдеры вида «сделал(а)» / «застрял(а)» /
    «залип(ла)» в статическом тексте (каталог техник, подписи чекина и т.п.)
    на форму нужного рода. Пол 'N' (не указан) оставляет текст как есть —
    исходную нейтральную запись с обоими вариантами."""
    if gender not in ('F', 'M'):
        return text
    male = gender == 'M'
    for placeholder, (m, f) in _PERSONALIZE_IRREGULAR.items():
        text = text.replace(placeholder, m if male else f)
    if male:
        text = re.sub(r'(\w+)\(ла\)', r'\1', text)
        text = re.sub(r'(\w+)\(а\)', r'\1', text)
    else:
        text = re.sub(r'(\w+)\(ла\)', r'\1ла', text)
        text = re.sub(r'(\w+)\(а\)', r'\1а', text)
    return text

def md_escape(text):
    """Экранирует спецсимволы legacy Markdown (_ * ` [) в свободном
    пользовательском тексте перед подстановкой в сообщение с
    parse_mode="Markdown". Без этого непарный символ в тексте задачи/дневника
    (например одиночное подчёркивание) роняет отправку с BadRequest —
    а если это происходит в finish_morning/finish_evening ПОСЛЕ записи в БД,
    но ДО return ConversationHandler.END, диалог зависает в последнем
    состоянии и следующее обычное сообщение пользователя утекает в него."""
    if not text:
        return text
    for ch in ("_", "*", "`", "["):
        text = text.replace(ch, "\\" + ch)
    return text

# ── ОТКЛЮЧАЕМЫЕ ПОЛЯ РИТУАЛА ────────────────────────────────────────────────
# Только ситуативные "мягкие" поля — задачи A/B/C, чек-лист выполненного и
# уровень энергии остаются обязательными, это не декорация ритуала, а его
# механика.
TOGGLEABLE_FIELDS = [
    ("m_writing",    "📝 Свободное письмо"),
    ("m_gratitude",  "🙏 Благодарность"),
    ("m_child",      "💛 Внутренний ребёнок"),
    ("e_ach",        "⭐ Достижения дня"),
    ("e_praise",     "🎉 Похвали себя"),
    ("e_highlights", "✨ Яркие моменты дня"),
    ("e_selfcare",   "🧩 Какие техники применял(а)"),
]

# e_selfcare — множественный выбор, отмечается как "пройден" отдельным
# ключом e_selfcare_done (см. RESUME_FIELDS_EVENING) — сам "e_selfcare"
# занят списком выбранных техник, а не флагом прохождения шага.
_TOGGLE_TO_RESUME_KEY = {"e_selfcare": "e_selfcare_done"}

def is_field_disabled(user, key):
    return key in (user.get("disabled_fields") or "").split(",")

SKIP_STREAK_NUDGE_THRESHOLD = 3  # столько подряд пропусков — и бот сам предложит отключить поле

def _parse_streaks(user):
    raw = user.get("skip_streaks") or ""
    return dict(item.split(":") for item in raw.split(",") if ":" in item)

def bump_skip_streak(uid, key):
    """Увеличивает счётчик подряд идущих пропусков поля key (сбрасывается
    при первом реальном ответе — см. reset_skip_streak). Возвращает новое
    значение — по нему решаем, не пора ли предложить отключить поле."""
    user = get_user(uid)
    streaks = _parse_streaks(user)
    streaks[key] = str(int(streaks.get(key, 0)) + 1)
    update_user(uid, skip_streaks=",".join(f"{k}:{v}" for k, v in streaks.items()))
    return int(streaks[key])

def reset_skip_streak(uid, key):
    user = get_user(uid)
    streaks = _parse_streaks(user)
    if key in streaks:
        del streaks[key]
        update_user(uid, skip_streaks=",".join(f"{k}:{v}" for k, v in streaks.items()))

def disable_field_kb(key):
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("Отключить этот вопрос", callback_data=f"quickdisable_{key}")],
        [InlineKeyboardButton("Не сейчас", callback_data="dismiss_nudge")],
    ])

async def maybe_send_skip_nudge(message, uid, key):
    """После SKIP_STREAK_NUDGE_THRESHOLD пропусков подряд — предлагает
    отключить поле насовсем вместо того чтобы молча продолжать спрашивать
    то, что человек явно не хочет заполнять."""
    streak = bump_skip_streak(uid, key)
    if streak == SKIP_STREAK_NUDGE_THRESHOLD:
        label = dict(TOGGLEABLE_FIELDS).get(key, key)
        await message.reply_text(
            f"Заметил — уже несколько раз подряд пропускаешь «{label}». "
            "Могу отключить этот вопрос насовсем, чтобы он больше не появлялся "
            "(включить обратно можно в любой момент через ⚙️ Настройки → Редактировать отчёты).",
            reply_markup=disable_field_kb(key)
        )

TASK_FIELDS = [("focus", "A"), ("b1", "B1"), ("b2", "B2"), ("c1", "C1"), ("c2", "C2"), ("c3", "C3")]

def build_tasks_summary(morning_data, done_set=None):
    """Формирует текстовый список задач из утреннего дневника.

    Всегда показывает буквенную метку (A/B1/B2/C1/C2/C3, см. TASK_FIELDS),
    даже для уже выполненных задач — галочка ✅ здесь не используется: в
    списке "что нужно сделать" она читается как "уже сделано" и сбивает с
    толку, даже если формально верна (жалоба тестировщицы Виктории).
    """
    lines = []
    for key, icon in TASK_FIELDS:
        val = morning_data.get(key)
        if val:
            lines.append(f"{icon}: {md_escape(val)}")
    return "\n".join(lines) if lines else "_задачи не заданы_"

def next_undone_task(morning_data, done_set=None):
    """Первая ещё не отмеченная выполненной задача дня (A → B1 → B2 → C1 → C2 → C3)."""
    done_set = done_set or set()
    for key in ("focus", "b1", "b2", "c1", "c2", "c3"):
        val = morning_data.get(key)
        if val and key not in done_set:
            return md_escape(val)
    return None

def get_today_context(user):
    """(today_iso, morning_data, done_set) для user — эта тройка нужна почти
    везде, где бот показывает "задачи на сегодня": маячок, коуч, фокус-таймер,
    дневной чекин, меню задач. Централизует таймзону пользователя вместо
    повторения naive date.today() в каждом месте."""
    uid = user["user_id"]
    today = datetime.now(get_user_tz(user)).date().isoformat()
    morning = get_diary(uid, "morning", today)
    done_set = set(get_diary(uid, "tasks_done", today).get("done", []))
    return today, morning, done_set

def mark_tasks_done(uid, keys, for_date):
    """Отмечает задачи (ключи TASK_FIELDS) выполненными в общем tasks_done —
    том же хранилище, что использует меню 📋 Задачи и вечерний чек-лист."""
    done_data = get_diary(uid, "tasks_done", for_date)
    done = set(done_data.get("done", []))
    done.update(keys)
    save_diary(uid, "tasks_done", {"done": list(done)}, for_date=for_date)

def midday_kb(morning=None, done_set=None):
    """Клавиатура дневного чекина — используется и в 13:00-уведомлении,
    и в маячке, и в повторной проверке после отдыха.

    Чекбокс ▫️/✅ на каждой задаче — тот же _task_checkbox_rows и тот же
    task_done_callback, что и в 📋 Задачи: можно отметить любую конкретную
    задачу прямо отсюда, не только последовательно A→B→C (фидбек Виктории —
    раньше здесь была только одна кнопка прогресса, без возможности
    отметить, что уже сделано именно сейчас)."""
    morning = morning or {}
    done_set = done_set or set()

    rows = _task_checkbox_rows(morning, done_set)
    existing_keys = [key for key, _ in TASK_FIELDS if morning.get(key)]
    all_done = bool(existing_keys) and all(key in done_set for key in existing_keys)

    if not all_done:
        rows.append([InlineKeyboardButton("🎉 Все задачи сделаны", callback_data="mid_all_done")])
    rows.append([InlineKeyboardButton("☕ Отдыхаю 10-15 мин", callback_data="mid_resting")])
    rows.append([InlineKeyboardButton("😬 Прокрастинирую", callback_data="mid_procr")])
    return InlineKeyboardMarkup(rows)


