# Финал онбординга — что предложить прямо сейчас. Не 3 бакета (утро/день/
# вечер), как для вернувшихся пользователей в start(): только что
# зарегистрировавшийся ещё ничего сегодня не заполнял, так что "поставить
# цели" одинаково уместно и в 10:00, и в 15:00 — до вечера один бакет.
def onboard_cta_text_and_kb(hour):
    if hour < 18:
        return (
            "Прямо сейчас — самое время начать: жми ☀️ Утро, чтобы поставить цели на сегодня.",
            morning_cta_kb()
        )
    return (
        "Вечер — хорошее время подвести итог и настроиться на завтра.",
        evening_cta_kb()
    )

def onboard_final_offer_text(hour):
    if hour < 18:
        return "Я ещё не рассказал, что вообще происходит дальше. Хочешь коротко объясню, или сразу начнём?"
    return "Я ещё не рассказал, что вообще происходит дальше. Хочешь коротко объясню, или сразу спланируем завтра?"

def onboard_final_offer_kb(hour):
    _, action_kb = onboard_cta_text_and_kb(hour)
    rows = [[InlineKeyboardButton("📖 Расскажи, как это работает", callback_data="onboard_explain_late")]]
    rows += action_kb.inline_keyboard
    return InlineKeyboardMarkup(rows)

async def send_onboarding_final(message, uid):
    user = get_user(uid)
    hour = datetime.now(get_user_tz(user)).hour
    if str(user.get("onboard_explained") or "0") == "1":
        text, kb = onboard_cta_text_and_kb(hour)
        await message.reply_text(text, reply_markup=kb)
    else:
        await message.reply_text(onboard_final_offer_text(hour), reply_markup=onboard_final_offer_kb(hour))

def today_str(tz=None):
    return datetime.now(tz or pytz.timezone(USER_TIMEZONE)).strftime("%d %B %Y")

# Не "навыки на день", а сама механика бота — их место в онбординге и
# в разделе 🧠 Навыки, а не в случайной ротации наравне с ситуативными техниками.
DAILY_SKILL_EXCLUDE = {"Список дел", "Приоритеты"}

def _daily_skill_indices(user):
    """Пул индексов SKILLS, из которого выбирается навык дня — с учётом
    struggles (если заданы в онбординге) и без DAILY_SKILL_EXCLUDE. Вынесено
    отдельно от get_daily_skill, чтобы reroll_daily_skill мог найти "следующий"
    индекс в том же самом пуле, а не пересчитывать его отдельно и рисковать
    рассинхроном."""
    struggles = [s for s in (user.get("struggles") or "").split(",") if s]
    pool = []
    if struggles:
        keywords = set()
        for s in struggles:
            keywords.update(PROBLEM_TO_SKILLS.get(s, []))
        pool = [i for i, sk in enumerate(SKILLS) if any(kw in sk["name"] for kw in keywords)]

    indices = pool or list(range(len(SKILLS)))
    indices = [i for i in indices if not any(ex in SKILLS[i]["name"] for ex in DAILY_SKILL_EXCLUDE)] or indices
    return indices

def get_daily_skill(uid):
    """Возвращает навык дня — меняется каждый день (по таймзоне пользователя),
    если только пользователь не переопределил его сегодня кнопкой
    «🔄 Другой навык» (см. reroll_daily_skill) — тогда до конца дня
    возвращается именно сохранённый выбор, а не хэш заново.

    Используем hashlib, а не встроенный hash(): для строк он рандомизирован
    per-process (PYTHONHASHSEED), так что после каждого рестарта бота навык
    дня для той же даты мог бы внезапно смениться.

    Если при онбординге отмечены главные трудности (user.struggles) — ротация
    идёт только среди навыков, связанных с этими трудностями (PROBLEM_TO_SKILLS),
    а не среди всех подряд. Без выбранных трудностей — как раньше, по всем.
    """
    user = get_user(uid)
    today = datetime.now(get_user_tz(user)).date().isoformat()

    override_date, _, override_name = (user.get("daily_skill_override") or "").partition("|")
    if override_date == today:
        for sk in SKILLS:
            if sk["name"] == override_name:
                return sk

    digest = hashlib.md5(f"{today}{uid}".encode()).hexdigest()
    indices = _daily_skill_indices(user)
    idx = indices[int(digest, 16) % len(indices)]
    return SKILLS[idx]

def reroll_daily_skill(uid):
    """Кнопка «🔄 Другой навык» — переключает навык дня на следующий в том
    же пуле (по кругу) и запоминает выбор в БД до конца дня. Без сохранения
    выбор слетел бы обратно к хэш-навыку при любом следующем показе."""
    user = get_user(uid)
    today = datetime.now(get_user_tz(user)).date().isoformat()
    current_idx = SKILLS.index(get_daily_skill(uid))
    indices = _daily_skill_indices(user)
    pos = indices.index(current_idx) if current_idx in indices else -1
    next_skill = SKILLS[indices[(pos + 1) % len(indices)]]
    update_user(uid, daily_skill_override=f"{today}|{next_skill['name']}")
    return next_skill

# ── ONBOARDING ─────────────────────────────────────────────────────────────
async def start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    init_db()
    clear_awaiting_flags(ctx, update)
    user = get_user(uid)

    # Если уже зарегистрирован — сразу предложить нужный блок по времени суток
    if user["name"]:
        hour = datetime.now(get_user_tz(user)).hour
        if hour < 12:
            await update.message.reply_text(
                f"С возвращением, {user['name']}! Сейчас утро — самое время настроиться на день 👇",
                reply_markup=morning_cta_kb()
            )
        elif hour < 18:
            await update.message.reply_text(
                f"С возвращением, {user['name']}! Сейчас день — работаем 👇",
                reply_markup=menu_button_kb()
            )
        else:
            await update.message.reply_text(
                f"С возвращением, {user['name']}! Сейчас вечер — время подвести итоги дня 👇",
                reply_markup=evening_cta_kb()
            )
        return ConversationHandler.END

    await update.message.reply_text(
        "👋 Привет! Я *ADHD Buddy* — помощник для людей с СДВГ и всех, у кого есть трудности с фокусом и прокрастинацией.\n\n"
        "🧠 *Чем помогу:*\n"
        "• Преодолевать фрустрацию и прокрастинацию\n"
        "• Строить структуру дня без лишнего давления\n"
        "• Замечать прогресс и не терять мотивацию\n\n"
        "Как тебя зовут?",
        parse_mode="Markdown"
    )
    return ONBOARD_NAME

async def got_name(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    name = update.message.text.strip()
    if len(name) > 30:
        await update.message.reply_text("Имя слишком длинное, напиши покороче:")
        return ONBOARD_NAME
    ctx.user_data["onboard_name"] = name
    # Сохраняем имя в БД сразу — чтобы оно не потерялось при перезапуске бота
    update_user(update.effective_user.id, name=name)
    await update.message.reply_text(
        f"Отлично, {name}! Как мне к тебе обращаться?",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Как к нему", callback_data="gender_M"),
             InlineKeyboardButton("Как к ней", callback_data="gender_F")],
            [InlineKeyboardButton("Другое", callback_data="gender_N")],
        ])
    )
    return ONBOARD_GENDER

async def got_gender(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    uid = q.from_user.id
    # ctx.user_data может быть пустым если ConversationHandler перезапустился — берём имя из БД
    name = ctx.user_data.get("onboard_name") or get_user(uid).get("name", "")
    gender = "M" if q.data == "gender_M" else ("F" if q.data == "gender_F" else "N")
    update_user(uid, gender=gender)  # имя уже сохранено в got_name, не перезаписываем

    await q.message.reply_text(f"Приятно познакомиться, {name}! 🙂")
    await asyncio.sleep(0.4)
    ctx.user_data["onboard_problems"] = []
    await q.message.reply_text(
        "С чем тебе труднее всего? Пройдёмся по нескольким темам, отметь то, что откликается — "
        "по этому я подскажу конкретные вещи под тебя, а не буду грузить всем подряд.",
    )
    await asyncio.sleep(0.3)
    await send_problem_group(q.message, ctx, 0)
    return ConversationHandler.END

async def toggle_problem(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    _, group_idx_str, key = q.data.split("_", 2)
    group_idx = int(group_idx_str)
    selected = ctx.user_data.setdefault("onboard_problems", [])
    if key in selected:
        selected.remove(key)
    else:
        selected.append(key)
    await q.message.edit_reply_markup(reply_markup=problem_group_kb(group_idx, selected))

async def problem_group_next(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    next_idx = int(q.data.replace("pn_", "")) + 1
    await send_problem_group(q.message, ctx, next_idx)

async def problems_done(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    selected = ctx.user_data.get("onboard_problems", [])
    update_user(uid, struggles=",".join(selected))
    if not selected:
        await _onboard_prompt_city(q, ctx, update)
        return
    name = ctx.user_data.get("onboard_name") or get_user(uid).get("name", "")
    await q.message.reply_text(
        f"{name}, рассказать, как именно я помогу с этим?",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Расскажи", callback_data="onboard_explain_yes")],
            [InlineKeyboardButton("Не надо, давай сразу", callback_data="onboard_explain_no")],
        ])
    )

async def _onboard_prompt_city(q, ctx, update):
    await q.message.reply_text(
        "🌍 *Из какого ты города?*\n\n"
        "Это нужно для правильного времени уведомлений — "
        "чтобы утреннее уведомление приходило в 9 утра *твоего* города, "
        "а не в 3 ночи 😅\n\n"
        "Просто напиши название города:",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("Пропустить", callback_data="onboard_done")
        ]])
    )
    clear_awaiting_flags(ctx, update)
    ctx.user_data["awaiting_city"] = True

async def onboard_explain_no(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    await _onboard_prompt_city(q, ctx, update)

# Текст объяснения "как я работаю" собран отдельными шагами (а не одним
# asyncio.sleep-каскадом), чтобы можно было пейсить его кнопками "Логично"/
# "Ясно" — следующее сообщение приходит только по нажатию, не заливая
# пользователя текстом сразу. Используется в двух точках входа: во время
# онбординга (onboard_explain_yes, then="city" — ведёт дальше к вопросу о
# городе) и после онбординга по кнопке "Расскажи" (onboard_explain_late,
# then="cta" — ведёт к предложению начать прямо сейчас).
async def send_explain_step(update: Update, ctx: ContextTypes.DEFAULT_TYPE, step: int, then: str):
    q = update.callback_query
    uid = q.from_user.id
    gender = get_user(uid)["gender"]
    name = md_escape(ctx.user_data.get("onboard_name") or get_user(uid).get("name", ""))
    selected = ctx.user_data.get("onboard_problems") or [
        s for s in (get_user(uid).get("struggles") or "").split(",") if s
    ]
    lines = [PROBLEM_HELP_TEXT[k] for k in selected if k in PROBLEM_HELP_TEXT]

    if step == 1:
        if lines:
            text = (
                f"{name}, вот как мы будем работать вместе: утром ставим 1-2 главные задачи на день, "
                "в течение дня я слежу как идут дела и подсказываю если что-то забуксовало, "
                "а вечером подводим итоги — и обязательно засчитываем победы, даже маленькие. "
                "Это не разовый совет, а привычка, которая тренируется каждый день."
            )
        else:
            text = (
                "У мозга с СДВГ мотивация работает иначе, чем у большинства людей: она загорается от "
                "интереса и срочности, а не от важности самой задачи. Поэтому важное, но неинтересное "
                "и несрочное — откладывается, и дело не в лени и не в силе воли.\n\n"
                "Ждать, пока «само появится» желание, можно бесконечно. Есть ещё гиперфокус — он иногда "
                "помогает залпом сделать много, но потом изматывает и накрывает отходняк, так что "
                "опираться только на него не получится. Помогает третье — внешняя структура, которая "
                "толкает начать, даже без прилива энергии или гиперфокуса. Это и есть моя работа "
                "каждый день:"
            )
        await q.message.reply_text(
            text, parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Логично", callback_data=f"expl_2_{then}")]])
        )
        return

    if step == 2:
        if lines:
            text = "Вот что конкретно предложу с твоими сложностями:\n\n" + "\n\n".join(lines)
        else:
            text = (
                "☀️ *Утром* — помогаю настроиться на день: разминка для тела, выгрузка из головы всех "
                "мыслей — полезных и тревожных, — и задачи на день. Идеи для задач можно закидывать "
                "в список дел в течение дня, а утром просто выбрать готовое.\n\n"
                "☕ *Днём* — проверяю, как дела: не начал(а) ли прокрастинировать, плюс "
                "маячки-напоминания в течение дня, а если что-то не идёт — подсказываю конкретную "
                "технику из DBT-протокола для взрослых с СДВГ.\n\n"
                "🌙 *Вечером* — вспоминаем день, присваиваем себе свои победы (даже маленькие — это "
                "важно), и ставим план на завтра."
            )
        await q.message.reply_text(
            personalize(text, gender), parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Ясно", callback_data=f"expl_3_{then}")]])
        )
        return

    # step == 3 — финал, дальше ведём к реальному следующему шагу (город/CTA),
    # без дополнительной кнопки-подтверждения: кнопка следующего шага и есть продолжение.
    if lines:
        goals = [PROBLEM_GOAL[k] for k in selected if k in PROBLEM_GOAL]
        goals_text = ", ".join(goals)
        # "Слишком много в голове" решается через коуча, а не отдельной фичей —
        # даём прямую кнопку туда, а не только упоминание в тексте.
        goal_kb = InlineKeyboardMarkup([[InlineKeyboardButton("🤖 Открыть коуча", callback_data="go_coach")]]) if "overload" in selected else None
        await q.message.reply_text(
            f"Цель — не просто пережить сегодня, а натренировать навык: {goals_text}. "
            "Со временем это начинает получаться само, без подсказок.\n\n"
            "В основе — не мотивационные фразы, а конкретные техники из DBT-тренинга для взрослых с СДВГ "
            "и когнитивно-поведенческой терапии (протокол Safren).\n\n"
            "_Если какой-то вопрос не заходит — его можно насовсем отключить: "
            "⚙️ Настройки → Редактировать отчёты._",
            parse_mode="Markdown",
            reply_markup=goal_kb
        )
    else:
        await q.message.reply_text(
            personalize(
                "Общая задача — сформировать привычку: строить структуру дня, мягко входить в него, "
                "держать фокус на приоритетах и замечать всё хорошее, что было. И по кругу, день за днём.\n\n"
                "Постепенно привыкаешь замечать, что сам(а) ставишь задачи и выполняешь их — и "
                "самооценка становится устойчивее.\n\n"
                "_Если какой-то вопрос не заходит — его можно насовсем отключить: "
                "⚙️ Настройки → Редактировать отчёты._",
                gender
            ),
            parse_mode="Markdown"
        )

    await asyncio.sleep(0.4)
    if then == "city":
        await _onboard_prompt_city(q, ctx, update)
    else:
        user = get_user(uid)
        text, kb = onboard_cta_text_and_kb(datetime.now(get_user_tz(user)).hour)
        await q.message.reply_text(text, reply_markup=kb)

async def onboard_explain_step(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    _, step_str, then = q.data.split("_", 2)
    await send_explain_step(update, ctx, step=int(step_str), then=then)

async def onboard_explain_yes(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    update_user(q.from_user.id, onboard_explained="1")
    await send_explain_step(update, ctx, step=1, then="city")

async def onboard_explain_late(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    update_user(q.from_user.id, onboard_explained="1")
    await send_explain_step(update, ctx, step=1, then="cta")

async def onboard_done(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    ctx.user_data["awaiting_city"] = False
    await q.message.reply_text(
        "🔔 *Последний шаг — уведомления*\n\n"
        "Бот пишет три раза в день: утром, днём и вечером "
        "(по умолчанию: 09:00 · 13:00 · 21:00) — они уже включены.\n\n"
        "Если не хочешь их получать, можешь отключить.",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("✅ Оставить включёнными", callback_data="onboard_notif_on")],
            [InlineKeyboardButton("🔕 Отключить", callback_data="onboard_notif_skip")],
        ])
    )

PIN_CHAT_TIP = (
    "📌 *Совет напоследок*\n\n"
    "Закрепи этот чат в Телеграме (зажми на нём в списке чатов → «Закрепить») — "
    "тогда бот всегда будет сверху и не потеряется среди других переписок. "
    "Для ежедневного инструмента это реально важно."
)

async def onboard_notif_on(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    update_user(uid, notif_enabled=1)
    await q.message.reply_text(
        "✅ *Уведомления включены!*\n\n"
        "По умолчанию: ☀️ 09:00 · ☕ 13:00 · 🌙 21:00\n"
        "Изменить время можно в ⚙️ Настройки.",
        parse_mode="Markdown"
    )
    await q.message.reply_text(PIN_CHAT_TIP, parse_mode="Markdown")
    await send_onboarding_final(q.message, uid)

async def onboard_notif_skip(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    update_user(uid, notif_enabled=0)
    await q.message.reply_text(
        "Окей, отключил. Включить уведомления можно в любой момент через ⚙️ Настройки."
    )
    await q.message.reply_text(PIN_CHAT_TIP, parse_mode="Markdown")
    await send_onboarding_final(q.message, uid)

# ── MORNING FLOW ───────────────────────────────────────────────────────────
async def morning_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    uid = q.from_user.id
    if _evening_conv is not None:
        _evening_conv._conversations.pop((update.effective_chat.id, uid), None)
    clear_awaiting_flags(ctx, update)
    user = get_user(uid)
    today_iso = datetime.now(get_user_tz(user)).date().isoformat()

    # Если сегодняшнее утро уже начато (пройден хотя бы один шаг), но не
    # закончено — продолжаем с первого непройденного шага, а не заново с
    # разминки. Раньше повторный заход (например по кнопке в напоминании)
    # всегда перезапускал morning_start с нуля и стирал прогресс.
    resuming = (
        ctx.user_data.get("m_progress_date") == today_iso
        and any(key in ctx.user_data for key, _, _ in RESUME_FIELDS)
    )
    if resuming:
        for key, state, ask_fn in RESUME_FIELDS:
            if key not in ctx.user_data:
                stopped = g(user["gender"], "остановился", "остановилась")
                await q.message.reply_text(f"↩️ Продолжаем с того места, где {stopped} сегодня утром:")
                await ask_fn(q.message, ctx, user["gender"])
                return state
        # Все шаги уже пройдены (крайний случай — finish_morning не успел
        # отработать) — начинаем заново, ниже.

    # Недописанное утро за ПРЕДЫДУЩИЙ день (например, оборвалась связь и
    # человек вернулся уже на следующие сутки) — раньше молча стиралось
    # прямо здесь при сбросе на новый день. Теперь сохраняем то, что успели
    # заполнить, в дневник того дня, а не теряем безвозвратно.
    stale_date = ctx.user_data.get("m_progress_date")
    if (stale_date and stale_date != today_iso
            and any(key in ctx.user_data for key, _, _ in RESUME_FIELDS)):
        checkpoint_morning_progress(ctx, uid, stale_date)

    ctx.user_data["m_progress_date"] = today_iso
    for key, _, _ in RESUME_FIELDS:
        ctx.user_data.pop(key, None)
    ctx.user_data.pop("quick_morning", None)
    # Протухшие с давних времён ключи старого пошагового ритуала (см.
    # _merged_task_fields) — сами по себе больше не читаются, но чистим на
    # каждый новый день на случай, если у пользователя они годами лежат
    # в персистентном user_data с версий бота до этого рефакторинга.
    for key in TASK_KEYS:
        ctx.user_data.pop(f"m_{key}", None)

    name = md_escape(user["name"])
    gender = user["gender"]
    motiv = random.choice(MOTIVATIONS_F if gender == 'F' else MOTIVATIONS_M)

    # Показать вчерашние планы, если есть (только для приветственного текста —
    # постановка задач A/B/C сейчас идёт отдельно через 📋 Задачи/пул).
    ev = get_latest_evening_plan(uid)
    y_plan = {
        "a":  ev.get("e_a", ""),  "b1": ev.get("e_b1", ""), "b2": ev.get("e_b2", ""),
        "c1": ev.get("e_c1", ""), "c2": ev.get("e_c2", ""), "c3": ev.get("e_c3", ""),
    }
    plans_text = ""
    if y_plan["a"]:
        plans_text = f"\n\n⭐ Помни — сегодня тебе важно:\n🅰️ {md_escape(y_plan['a'])}"
        if y_plan["b1"]: plans_text += f"\n🅱️ {md_escape(y_plan['b1'])}"
        if y_plan["b2"]: plans_text += f"\n🅱️ {md_escape(y_plan['b2'])}"

    # Что вчера по факту осталось не сделано (не путать с y_plan выше — это
    # то, что человек сам решил перенести на сегодня вечером; здесь же —
    # объективный remainder из вчерашних A/B/C, которые не отметили ✅).
    yesterday_iso = (datetime.now(get_user_tz(user)).date() - timedelta(days=1)).isoformat()
    y_morning = get_diary(uid, "morning", yesterday_iso)
    y_done = set(get_diary(uid, "tasks_done", yesterday_iso).get("done", []))
    undone_yesterday = [y_morning[k] for k, _ in TASK_FIELDS if y_morning.get(k) and k not in y_done]
    undone_text = ""
    kb_rows = []
    skill = get_daily_skill(uid)
    skill_idx = SKILLS.index(skill)
    if undone_yesterday:
        undone_list = "\n".join(f"• {md_escape(t)}" for t in undone_yesterday)
        undone_text = (
            f"\n\n📌 *Вчера не {g(gender, 'успел', 'успела')}:*\n{undone_list}\n\n"
            "Это нормально — не обязательно доделывать именно это. Сегодня новый день: "
            "загляни в свой общий список дел и выбери то, что сейчас приоритетнее."
        )
        todolist_idx = next((i for i, s in enumerate(SKILLS) if "Список дел" in s["name"]), None)
        # Не дублируем кнопку, если навык дня и есть тот самый "Список дел"
        if todolist_idx is not None and todolist_idx != skill_idx:
            kb_rows.append([InlineKeyboardButton("📋 Как вести список дел", callback_data=f"skill_{todolist_idx}")])

    kb_rows.append([InlineKeyboardButton(f"🧠 Подробнее: {skill['name']}", callback_data=f"skill_{skill_idx}")])
    kb_rows.append([InlineKeyboardButton("🔄 Поменять навык", callback_data="reroll_skill")])
    reply_markup = InlineKeyboardMarkup(kb_rows)

    # Адаптивное приветствие по уровню энергии вечера
    last_energy = int(ev.get("e_energy", 0) or 0)
    energy_note = ""
    if last_energy in (1, 2):
        energy_note = (
            f"\n\n🔋 *Вчера был тяжёлый день* — ты {g(gender, 'отметил', 'отметила')} низкий уровень энергии.\n"
            "Сегодня можно взять темп помедленнее. Главное — одна задача A."
        )

    morning_greeting = (
        f"☀️ *Доброе утро, {name}!*\n"
        f"_{today_str(get_user_tz(user))}_\n\n"
        f"_{motiv}_{undone_text}{plans_text}{energy_note}\n\n"
        f"💡 *Навык дня:* {skill['name']}\n"
        f"_{skill['desc']}_"
    )
    try:
        await q.message.reply_text(morning_greeting, parse_mode="Markdown", reply_markup=reply_markup)
    except Exception as e:
        # Тот же класс сбоя, что в finish_morning/finish_evening — непарный
        # спецсимвол не покрытый md_escape не должен ронять диалог насовсем.
        print(f"Ошибка отправки утреннего приветствия uid={uid}: {e}")
        await q.message.reply_text(
            f"☀️ Доброе утро, {name}! 💡 Навык дня: {skill['name']}",
            reply_markup=reply_markup
        )
    await asyncio.sleep(0.5)

    # Если энергия была низкой — сразу предложить быстрый режим первой кнопкой
    if last_energy in (1, 2):
        warmup_kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("⚡ Только задачи (5 мин)", callback_data="morning_quick")],
            [InlineKeyboardButton("▶️ Полное утро с разминкой", callback_data="warmup_go")],
            [InlineKeyboardButton(f"✅ Разминку уже {g(gender, 'сделал', 'сделала')}", callback_data="warmup_done")],
        ])
        warmup_text = (
            "🏃 *Разминка или сразу к делу?*\n\n"
            "Вчера был тяжёлый день — можно пропустить разминку и сразу поставить задачи.\n"
            "_Даже в лёгкий день одна задача A — уже победа._"
        )
    else:
        warmup_kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("▶️ Начать разминку", callback_data="warmup_go")],
            [InlineKeyboardButton(f"✅ Уже {g(gender, 'сделал', 'сделала')}", callback_data="warmup_done")],
            [InlineKeyboardButton("Пропустить →", callback_data="skip_warmup")],
            [InlineKeyboardButton("⚡ Быстро — только задачи", callback_data="morning_quick")],
        ])
        warmup_text = (
            "🏃 *2 минуты утренней разминки*\n\n"
            "Тело нужно разбудить — это важно для мозга с СДВГ.\n\n"
            "_Это программа-минимум, просто чтобы напомнить и помочь начать. "
            "Если хочется — сделай свою разминку подольше, бот не ограничивает._"
        )

    await q.message.reply_text(warmup_text, parse_mode="Markdown", reply_markup=warmup_kb)
    return M_EXERCISE

async def warmup_go(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    msg = await q.message.reply_text("Начинаем! 🏃")
    for i, (name, hint) in enumerate(WARMUP):
        dots = "🟡"*(i+1) + "⚪"*(len(WARMUP)-i-1)
        await msg.edit_text(f"{dots}\n\n*{name}*\n_{hint}_\n\n⏱ 20 секунд...", parse_mode="Markdown")
        await asyncio.sleep(20)
    await msg.edit_text("✅ *Тело проснулось!* Теперь — настроимся.", parse_mode="Markdown")
    return await advance_morning(ctx, q.message, get_user(q.from_user.id)["gender"], q.from_user.id)

async def warmup_done(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    await q.message.reply_text("💪 Отлично, тело уже разбужено!")
    return await advance_morning(ctx, q.message, get_user(q.from_user.id)["gender"], q.from_user.id)

async def skip_warmup(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    return await advance_morning(ctx, q.message, get_user(q.from_user.id)["gender"], q.from_user.id)

async def morning_quick(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """«Быстро — только задачи»: пропускает и разминку, и мягкий ритуал
    (письмо/благодарность/ребёнок), сразу ведёт к постановке задач через
    📋 Задачи. Раньше вела в M_FOCUS — состояние, намеренно не
    зарегистрированное в states морning_conv (см. RESUME_FIELDS ниже),
    из-за чего диалог намертво зависал на первом же шаге. Теперь просто
    завершает ритуал сразу, как и остальные ветки после разминки."""
    q = update.callback_query; await q.answer()
    ctx.user_data["quick_morning"] = True
    ctx.user_data["m_writing"] = ""
    ctx.user_data["m_gratitude"] = ""
    ctx.user_data["m_child"] = ""
    await finish_morning(q.message, q.from_user.id, ctx)
    await send_morning_task_offer(q.message, q.from_user.id)
    return ConversationHandler.END

