# Шаги утреннего диалога по порядку, вместе с ключом ctx.user_data, который
# появляется как только шаг пройден (даже если ответ пустой — см. skip_m_*),
# и функцией, которая заново присылает вопрос этого шага. Используется в
# morning_start, чтобы при повторном заходе (после таймаута/случайного
# закрытия) продолжить с первого непройденного шага, а не с начала.
# Утренний ритуал — только практики (письмо/благодарность/ребёнок). Задачи
# больше НЕ часть этого линейного диалога (см. advance_morning ниже и
# morning_task_offer_yes/no) — по прямой просьбе Анны: "ритуалы отдельно,
# задачки отдельно". Постановка задач теперь идёт через 📋 Задачи, которую
# после ритуала предлагает открыть отдельное сообщение, а не встроенный шаг.
RESUME_FIELDS = [
    ("m_writing",   M_WRITING,   lambda msg, ctx, gender: ask_writing(msg)),
    ("m_gratitude", M_GRATITUDE, lambda msg, ctx, gender: ask_gratitude(msg, gender)),
    ("m_child",     M_CHILD,     lambda msg, ctx, gender: ask_child(msg, gender)),
]

async def advance_morning(ctx, message, gender, uid, from_key=None):
    """Переходит к следующему шагу утреннего ритуала после from_key (или с
    самого начала, если from_key=None), молча пропуская поля, отключённые
    в ⚙️ Настройки → Редактировать отчёты — как явный skip, только без
    самого вопроса. Использует тот же RESUME_FIELDS, что и резюме прерванного
    утра, поэтому отключённые поля корректно не считаются "недопройденными"
    при повторном заходе."""
    user = get_user(uid)
    start_idx = 0
    if from_key is not None:
        start_idx = next(i for i, (k, _, _) in enumerate(RESUME_FIELDS) if k == from_key) + 1
    for key, state, ask_fn in RESUME_FIELDS[start_idx:]:
        if is_field_disabled(user, key):
            ctx.user_data[key] = ""
            continue
        await ask_fn(message, ctx, gender)
        return state
    await finish_morning(message, uid, ctx)
    await send_morning_task_offer(message, uid)
    return ConversationHandler.END

async def pin_today_tasks(ctx, uid, sent_message):
    """Пинит сообщение с задачами дня, сняв старый пин (если остался, например
    если вчера не закрыли вечер и unpin не случился). В приватном чате с ботом
    пин доступен всегда, без прав администратора."""
    user = get_user(uid)
    old_id = user.get("pinned_msg_id") or ""
    if old_id:
        try:
            await ctx.bot.unpin_chat_message(chat_id=uid, message_id=int(old_id))
        except Exception:
            pass
    try:
        await ctx.bot.pin_chat_message(chat_id=uid, message_id=sent_message.message_id, disable_notification=True)
        update_user(uid, pinned_msg_id=str(sent_message.message_id))
    except Exception as e:
        print(f"Ошибка пина задач дня uid={uid}: {e}")

async def unpin_today_tasks(ctx, uid):
    user = get_user(uid)
    old_id = user.get("pinned_msg_id") or ""
    if not old_id:
        return
    try:
        await ctx.bot.unpin_chat_message(chat_id=uid, message_id=int(old_id))
    except Exception:
        pass
    update_user(uid, pinned_msg_id="")

TASK_KEYS = ("focus", "b1", "b2", "c1", "c2", "c3")

def _merged_task_fields(ctx, existing):
    """focus/b1/b2/c1/c2/c3 — всегда берём то, что уже стоит в БД (existing),
    задачи ставятся отдельно, через 📋 Задачи.

    С тех пор как шаги ритуала M_FOCUS/M_B1/... удалены, ctx.user_data
    больше НИКОГДА не заполняет "m_focus"/"m_b1"/... — ни один код это не
    делает. Раньше здесь всё равно проверялось ctx.user_data.get(f"m_{key}")
    "на всякий случай", и это оказалось активным багом: у бота включена
    PicklePersistence, так что user_data переживает рестарты и хранится
    годами — у пользователей, заставших ещё старый пошаговый ритуал, там
    годами лежат древние значения тех самых ключей. Раз "или" отдавал
    приоритет ctx.user_data, эти протухшие значения тихо перебивали
    актуальные задачи из БД при каждом проходе утреннего ритуала —
    один и тот же старый список задач "воскресал" день за днём независимо
    от того, что реально стояло в 📋 Задачи. ctx (параметр оставлен для
    единообразия сигнатуры, но больше не используется)."""
    return {key: existing.get(key, "") for key in TASK_KEYS}

def checkpoint_morning_progress(ctx, uid, for_date):
    """Сохраняет недописанное утро, прерванное и не продолженное в тот же
    день, в дневник этого дня как есть — без стрика и без сброса tasks_done
    (это не завершение дня, а спасение того, что успели заполнить)."""
    existing = get_diary(uid, "morning", for_date)
    save_diary(uid, "morning", {
        **_merged_task_fields(ctx, existing),
        "writing":  ctx.user_data.get("m_writing", ""),
        "gratitude":ctx.user_data.get("m_gratitude", ""),
        "child":    ctx.user_data.get("m_child", ""),
    }, for_date=for_date)

async def finish_morning(message, uid, ctx):
    user = get_user(uid)
    tz = get_user_tz(user)
    now_dt = datetime.now(tz)
    today = now_dt.date().isoformat()
    existing = get_diary(uid, "morning", today)
    task_fields = _merged_task_fields(ctx, existing)
    focus = task_fields["focus"]
    if focus: update_user(uid, focus=focus)
    # Момент заполнения утра — нужен маячку задач, чтобы не стрелять сразу
    # вслед, если утро заполнено поздно (см. send_task_beacon).
    update_user(uid, morning_filled_at=now_dt.isoformat())

    save_diary(uid, "morning", {
        **task_fields,
        "writing":  ctx.user_data.get("m_writing", ""),
        "gratitude":ctx.user_data.get("m_gratitude", ""),
        "child":    ctx.user_data.get("m_child", ""),
    }, for_date=today)
    # Отметки "выполнено" сбрасываем только для полей, текст которых
    # реально поменялся — иначе стираем честные отметки, поставленные
    # через 📋 Задачи ещё до прохождения ритуала.
    changed_keys = {k for k in TASK_KEYS if task_fields[k] != existing.get(k, "")}
    if changed_keys:
        done_data = get_diary(uid, "tasks_done", today)
        done_list = [k for k in done_data.get("done", []) if k not in changed_keys]
        if len(done_list) != len(done_data.get("done", [])):
            save_diary(uid, "tasks_done", {"done": done_list}, for_date=today)
    add_streak(uid, for_date=today)

    morning_for_summary = task_fields
    tasks_text = build_tasks_summary(morning_for_summary)
    tasks_text = "\n" + tasks_text if tasks_text != "_задачи не заданы_" else "_(задачи не заданы)_"

    # AI мотивация если есть ключ
    ai_msg = ""
    if ANTHROPIC_KEY and focus:
        ai_msg = await ai_morning_boost(user["name"], user["gender"], focus)
        if ai_msg: ai_msg = f"\n\n🤖 _{ai_msg}_"

    sent = None
    try:
        sent = await message.reply_text(
            f"✅ *Утро {g(user['gender'], 'записано', 'записана')}!*\n"
            f"{tasks_text}"
            f"{ai_msg}\n\n"
            f"{g(user['gender'], 'Вперёд', 'Вперёд')}, {md_escape(user['name'])}! 💪",
            parse_mode="Markdown",
            reply_markup=menu_button_kb()
        )
    except Exception as e:
        # Даже если сборка Markdown-сообщения не удалась (например из-за
        # спецсимвола, который md_escape не покрыл) — диалог уже должен
        # завершиться штатно, а не зависнуть в последнем ConversationHandler-состоянии.
        print(f"Ошибка отправки итога утра uid={uid}: {e}")
        sent = await message.reply_text(
            f"✅ Утро записано! {g(user['gender'], 'Вперёд', 'Вперёд')}, {user['name']}! 💪",
            reply_markup=menu_button_kb()
        )

    # Пиним, только если реально есть что закреплять — не пустое "задачи не заданы".
    if sent is not None and any(morning_for_summary.values()):
        await pin_today_tasks(ctx, uid, sent)

async def send_morning_task_offer(message, uid):
    """После утреннего ритуала (только практики) — отдельное необязательное
    предложение поставить задачи, а не встроенный шаг того же диалога. По
    просьбе Анны: «ритуалы отдельно, задачки отдельно»."""
    await message.reply_text(
        "📋 Поставить задачи на сегодня?",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Да, поставить", callback_data="morning_tasks_yes")],
            [InlineKeyboardButton("Не сейчас", callback_data="morning_tasks_no")],
        ])
    )

async def morning_task_offer_yes(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Открывает 📋 Задачи (уже готовый экран добавления/правки — не новый
    сценарий) и следом спрашивает время начала работы для напоминания."""
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()
    morning = get_diary(uid, "morning", today)
    done_set = set(get_diary(uid, "tasks_done", today).get("done", []))
    text, kb = _tasks_text_and_kb(morning, done_set, get_user(uid)["gender"])
    await q.message.reply_text(text, parse_mode="Markdown", reply_markup=kb)

    clear_awaiting_flags(ctx, update)
    ctx.user_data["awaiting_work_start"] = True
    await q.message.reply_text(
        "🚪 Во сколько сегодня начинаешь работать?\n\n"
        "Пришлю напоминание с задачами в это время. Формат: *ЧЧ:ММ* (например `10:00`)",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Не сейчас", callback_data="skip_work_start")]])
    )

async def morning_task_offer_no(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    await q.message.reply_text(
        "Хорошо — задачи всегда можно поставить в 📋 Задачи, когда будешь готов(а).",
        reply_markup=menu_button_kb()
    )

async def skip_work_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    ctx.user_data["awaiting_work_start"] = False
    await q.message.reply_text("Окей, без напоминания.", reply_markup=menu_button_kb())

# ── EVENING FLOW ───────────────────────────────────────────────────────────

def tasks_done_kb(morning, done):
    rows = []
    for key, icon in TASK_FIELDS:
        text = morning.get(key)
        if not text: continue
        mark = "✅" if key in done else "▫️"
        label = f"{mark} {icon}: {text}"
        rows.append([InlineKeyboardButton(label[:60], callback_data=f"td_{key}")])
    rows.append([InlineKeyboardButton("Готово ✅", callback_data="td_done")])
    return InlineKeyboardMarkup(rows)

async def ask_tasks_done(message, uid, ctx):
    # Утро/tasks_done всегда под обычной календарной датой (см.
    # get_today_context) — evening_day здесь не подходит: в окне 00:00-04:00
    # он сдвигает "сегодня" на вчера, и только что заполненное утро/отметки
    # из 📋 Задачи не находились бы.
    today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()
    morning = get_diary(uid, "morning", today)
    # Подхватываем отметки, уже сделанные днём в меню "📋 Задачи" —
    # иначе вечерний блок затирает их пустым списком.
    already_done = list(get_diary(uid, "tasks_done", today).get("done", []))
    ctx.user_data["e_tasks_done"] = already_done
    await message.reply_text(
        "✅ *Что из запланированного получилось?*\n\nОтметь выполненные задачи:",
        parse_mode="Markdown",
        reply_markup=tasks_done_kb(morning, already_done)
    )

async def toggle_task_done(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    key = q.data.replace("td_", "")
    done = ctx.user_data.setdefault("e_tasks_done", [])
    if key in done:
        done.remove(key)
    else:
        done.append(key)
    today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()
    morning = get_diary(uid, "morning", today)
    await q.message.edit_reply_markup(reply_markup=tasks_done_kb(morning, done))
    return E_TASKS_DONE

async def tasks_done_finish(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    user = get_user(uid)
    if is_field_disabled(user, "e_ach"):
        ctx.user_data["e_ach"] = ""
        return await advance_evening(ctx, q.message, user["gender"], uid, "e_ach")
    await ask_achievements(q.message, user["gender"], had_checklist=True)
    return E_ACH

async def ask_achievements(message, gender, had_checklist=False):
    if had_checklist:
        text = (
            "⭐ *Достижения дня*\n\n"
            "Помимо запланированного — что ещё сегодня получилось? "
            "Большое или маленькое — всё считается."
        )
    else:
        text = f"⭐ *Достижения дня*\n\n{g(gender, 'Чего достиг', 'Чего достигла')} сегодня? Большое или маленькое — всё считается."
    await message.reply_text(text, parse_mode="Markdown", reply_markup=skip_kb("skip_e_ach"))

async def evening_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    if _morning_conv is not None:
        _morning_conv._conversations.pop((update.effective_chat.id, uid), None)
    clear_awaiting_flags(ctx, update)
    user = get_user(uid)
    today = evening_day(get_user_tz(user)).isoformat()

    # Резюме прерванного вечера — см. комментарий у RESUME_FIELDS_EVENING и
    # у аналогичной ветки в morning_start. Без этого набранный текст (планы
    # на завтра и т.п.) молча терялся при повторном заходе после перерыва.
    resuming = (
        ctx.user_data.get("e_progress_date") == today
        and any(key in ctx.user_data for key, _, _ in RESUME_FIELDS_EVENING)
    )
    if resuming:
        for key, state, ask_fn in RESUME_FIELDS_EVENING:
            if key not in ctx.user_data:
                stopped = g(user["gender"], "остановился", "остановилась")
                await q.message.reply_text(f"↩️ Продолжаем с того места, где {stopped} сегодня вечером:")
                await ask_fn(q.message, ctx, user["gender"])
                return state
        # Все шаги уже пройдены (крайний случай — finish_evening не успел
        # отработать) — начинаем заново, ниже.

    # Недописанный вечер за ПРЕДЫДУЩИЙ день (например, оборвалась связь и
    # человек вернулся уже на следующие сутки) — раньше молча стирался
    # прямо здесь при сбросе на новый день. Теперь сохраняем то, что успели
    # заполнить, в дневник того дня, а не теряем безвозвратно.
    stale_date = ctx.user_data.get("e_progress_date")
    if (stale_date and stale_date != today
            and any(key in ctx.user_data for key, _, _ in RESUME_FIELDS_EVENING)):
        checkpoint_evening_progress(ctx, uid, stale_date)

    ctx.user_data["e_progress_date"] = today
    for key, _, _ in RESUME_FIELDS_EVENING:
        ctx.user_data.pop(key, None)
    # e_selfcare — сам список выбранных техник, а не чекпоинт-ключ
    # (e_selfcare_done в RESUME_FIELDS_EVENING отмечает только "шаг пройден").
    # Без явного сброса вчерашний выбор оставался в ctx.user_data и
    # selfcare_kb показывал его уже отмеченным на новый вечер.
    ctx.user_data.pop("e_selfcare", None)

    # Утро всегда пишется/читается под обычной календарной датой (см.
    # morning_start/finish_morning/get_today_context) — в отличие от
    # evening_day, который в окне 00:00-04:00 сдвигает "сегодня" на вчера.
    # Раньше здесь искали утренний дневник по evening_day-дате "today" —
    # если вечер открывали в этом окне, только что заполненное утро не
    # находилось (get_diary смотрел не в ту дату).
    morning_today = datetime.now(get_user_tz(user)).date().isoformat()
    morning = get_diary(uid, "morning", morning_today)
    focus_recap = f"\n🎯 Фокус был: _{md_escape(morning['focus'])}_" if morning.get("focus") else ""
    streak_line = ""
    if not int(user.get("streak_hidden") or 0):
        streak = calc_streak(uid)
        streak_line = f"🔥 Стрик: *{streak} {'день' if streak==1 else 'дня' if streak<5 else 'дней'}*\n\n"

    evening_greeting = (
        f"🌙 *Хороший был день, {md_escape(user['name'])}!*\n"
        f"_{today_str(get_user_tz(user))}_{focus_recap}\n\n"
        f"{streak_line}"
        "Давай закроем этот день."
    )
    try:
        await q.message.reply_text(evening_greeting, parse_mode="Markdown")
    except Exception as e:
        # Тот же класс сбоя, что в morning_start/finish_morning/finish_evening —
        # непарный спецсимвол не покрытый md_escape не должен ронять диалог насовсем.
        print(f"Ошибка отправки вечернего приветствия uid={uid}: {e}")
        await q.message.reply_text(f"🌙 Хороший был день, {user['name']}! Давай закроем этот день.")
    await asyncio.sleep(0.5)

    if any(morning.get(key) for key, _ in TASK_FIELDS):
        await ask_tasks_done(q.message, uid, ctx)
        return E_TASKS_DONE
    else:
        if is_field_disabled(user, "e_ach"):
            ctx.user_data["e_ach"] = ""
            return await advance_evening(ctx, q.message, user["gender"], uid, "e_ach")
        await ask_achievements(q.message, user["gender"])
        return E_ACH

