BEACON_TEXTS = [
    "👀 *Маячок внимания*\n\nЗадачи дня:\n{tasks}\n\nЧто сейчас делаешь?",
    "⏱ *Стоп на секунду*\n\nЗадачи дня:\n{tasks}\n\nНад чем работаешь прямо сейчас?",
    "🔔 *Проверка*\n\nЗадачи дня:\n{tasks}\n\nКак дела? Всё по плану?",
    "👁 *Внимание, маячок*\n\nЗадачи дня:\n{tasks}\n\nВернёмся к задачам — что сейчас происходит?",
    "🧭 *Сориентируемся*\n\nЗадачи дня:\n{tasks}\n\nТы где сейчас по задачам?",
    "💡 *Короткая пауза*\n\nЗадачи дня:\n{tasks}\n\nНа чём сосредоточен(а) прямо сейчас?",
]

# ── ТИПЫ МАЯЧКА ──────────────────────────────────────────────────────────────
# Маячок по умолчанию — просто проверка задач (как раньше). Пользователь может
# дополнительно включить короткие техники, которые иногда встают в тот же
# слот вместо обычной проверки — не отдельным напоминанием (это удвоило бы
# число прерываний за день), а ротацией внутри одного и того же тика.
BEACON_TECHNIQUE_TYPES = [
    ("stop",      "🛑 Техника СТОП"),
    ("breathing", "🌬 Дыхание"),
    ("grounding", "👁 Заземление 5-4-3-2-1"),
    ("anchor",    "⚓ Якорь"),
]

BEACON_TECHNIQUE_PROMPTS = {
    "stop":      "🛑 *СТОП*\n\nЗамри на секунду. Оглянись — что вообще сейчас происходит вокруг и внутри тебя? Дальше продолжай осознанно, не на автомате.",
    "breathing": "🌬 *Дыхание*\n\nВдох на 4 счёта — выдох на 8. Повтори 5-6 раз подряд.",
    "grounding": "👁 *Заземление*\n\n5 предметов, которые видишь. 4 вещи, которые можешь потрогать. 3 звука, которые слышишь.",
    "anchor":    "⚓ *Якорь*\n\nВдави ноги в пол, выпрями спину, сожми пальцы. Найди 5 предметов вокруг, услышь 3-4 звука.",
}

# Ключи маячка ("breathing"/"grounding") имеют свои подписи в
# BEACON_TECHNIQUE_TYPES, которые НЕ совпадают дословно с "name" в каталоге
# SKILLS ("👁 Заземление 5-4-3-2-1" vs "👁 Техника заземления 5-4-3-2-1") —
# поэтому анимацию ищем через этот явный маппинг на канонические имена
# навыков, а не сравнением текста подписи.
BEACON_TECHNIQUE_SKILL_NAMES = {
    "breathing": "🌬 Дыхание",
    "grounding": "👁 Техника заземления 5-4-3-2-1",
}

BEACON_TECHNIQUE_WHY = (
    "Мозг с СДВГ легко теряет связь с телом и текущим моментом — застревает в задаче, "
    "в тревоге или в скролле, и сам этого не замечает. Короткие техники в течение дня — "
    "это внешний тычок, который возвращает в контакт с собой, до того как накопится "
    "перегруз или потеряется весь день."
)
WHY_EXPLANATIONS["beacon_technique"] = BEACON_TECHNIQUE_WHY

def _beacon_rotation_pool(user):
    """Список включённых типов техник для блока «напоминания с навыками».
    Обычная проверка задач (раньше была в этой же ротации как None) теперь
    отдельный, независимый блок — см. send_task_beacon."""
    return [k for k, _ in BEACON_TECHNIQUE_TYPES if k in (user.get("beacon_types") or "").split(",")]

def next_beacon_slot(uid):
    """Круговая ротация типов маячка — что выпадет в этот тик. Индекс
    хранится в БД (а не в памяти планировщика), чтобы не сбрасывался при
    рестарте процесса и не совпадал у всех пользователей одновременно.
    None, если ни одна техника не включена в "🎯 Типы маячка"."""
    user = get_user(uid)
    pool = _beacon_rotation_pool(user)
    if not pool:
        return None
    idx = int(user.get("beacon_rotation_idx") or "0") % len(pool)
    update_user(uid, beacon_rotation_idx=str((idx + 1) % len(pool)))
    return pool[idx]

async def beacon_technique_done(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """«✅ Сделал(а)» после техники маячка — сразу следом обычная проверка
    задач, тот же переход, что и после обычного тика маячка.

    Раньше при пустом утреннем дневнике (задачи ещё не поставлены) кнопка
    молча ничего не делала — ни ошибки, ни ответа, просто "не сработала".
    build_tasks_summary и midday_kb оба прекрасно работают с пустым
    morning ({}), так что ранний выход был не нужен и только терял тап."""
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    user = get_user(uid)
    _, morning, done_set = get_today_context(user)
    tasks = build_tasks_summary(morning, done_set)
    beacon_text = personalize(random.choice(BEACON_TEXTS).format(tasks=tasks), user["gender"])
    await q.message.reply_text(beacon_text, parse_mode="Markdown", reply_markup=midday_kb(morning, done_set))

def _in_beacon_hours(user, now):
    """Рабочие часы маячка — общие для обоих блоков напоминаний (задачи и
    навыки), настраиваются в ⚙️ Настройки."""
    start_h, start_m = map(int, (user.get("beacon_start") or "09:00").split(":"))
    end_h, end_m = map(int, (user.get("beacon_end") or "21:00").split(":"))
    now_minutes = now.hour * 60 + now.minute
    start_minutes, end_minutes = start_h * 60 + start_m, end_h * 60 + end_m
    if start_minutes <= end_minutes:
        return start_minutes <= now_minutes <= end_minutes
    # Окно через полночь (например 22:00–06:00) — вне [end, start) считается рабочим временем.
    return not (end_minutes < now_minutes < start_minutes)

async def send_task_beacon(app, user):
    """Напоминания по задачам — независимый блок настроек: периодически
    спрашивает «что сейчас делаешь?» по задачам дня. Частота и вкл/выкл —
    отдельно от напоминаний с навыками, см. send_skill_beacon."""
    try:
        uid = user["user_id"]
        if not int(user.get("beacon_enabled") or 0): return

        tz = get_user_tz(user)
        now = datetime.now(tz)
        interval_h = int(user.get("beacon_interval") or 2)

        if not _in_beacon_hours(user, now): return

        # beacon_last_sent почти всегда вчерашний в начале дня (маячок ещё не
        # стрелял сегодня) — интервал "с последней отправки" формально
        # огромный и проходит мгновенно. Раньше это значило "стреляй, как
        # только утро появится", даже если утро заполнено буквально минуту
        # назад. Берём более позднюю точку отсчёта из двух: последняя
        # отправка маячка ИЛИ момент, когда сегодня заполнили утро — и ждём
        # полный интервал именно от неё.
        baseline_dt = None
        for ts in (user.get("beacon_last_sent") or "", user.get("morning_filled_at") or ""):
            if not ts: continue
            try:
                dt = datetime.fromisoformat(ts).astimezone(tz)
                if baseline_dt is None or dt > baseline_dt:
                    baseline_dt = dt
            except Exception:
                pass
        if baseline_dt and (now - baseline_dt).total_seconds() < interval_h * 3600 - 30: return

        # Тот же случай, но со стороны дневного чекина: если утро заполнено
        # задолго до дневного чекина, а маячок пока не стрелял, дневной чекин
        # сам по себе только что закрыл ровно тот же вопрос "что сейчас
        # делаешь" — не дублируем его в ближайшие полчаса.
        if user.get("midday_sent_date") == now.date().isoformat():
            try:
                mh, mm = map(int, (user.get("notif_midday") or "13:00").split(":"))
                midday_dt = now.replace(hour=mh, minute=mm, second=0, microsecond=0)
                if 0 <= (now - midday_dt).total_seconds() < 1800: return
            except Exception:
                pass

        # Маячок спрашивает "что сейчас делаешь?" по задачам дня — бессмысленно
        # (и раздражает), пока эти задачи ещё не поставлены утром, даже если
        # рабочие часы маячка уже наступили
        today_iso, morning, done_set = get_today_context(user)
        if not morning: return
        tasks = build_tasks_summary(morning, done_set)

        beacon_text = personalize(random.choice(BEACON_TEXTS).format(tasks=tasks), user["gender"])
        await app.bot.send_message(
            chat_id=uid,
            text=beacon_text,
            parse_mode="Markdown",
            reply_markup=midday_kb(morning, done_set)
        )
        # Отмечаем как отправленный только после успешной отправки — иначе
        # временный сбой навсегда "съедает" этот тик маячка.
        update_user(uid, beacon_last_sent=now.isoformat())
    except Exception as e:
        print(f"Ошибка маячка задач uid={user.get('user_id')}: {e}")

def _skill_beacon_random_times(user, now, count):
    """N случайных моментов на сегодня внутри рабочих часов маячка,
    стратифицированных по равным интервалам (окно делится на count частей,
    внутри каждой — честно случайный момент) — так они не слипаются в кучу,
    но и не превращаются в жёсткий равный интервал. Детерминировано по
    uid+дате (seed), чтобы не хранить отдельно сгенерированный список и не
    пересчитывать его по-разному на каждом минутном тике."""
    start_h, start_m = map(int, (user.get("beacon_start") or "09:00").split(":"))
    end_h, end_m = map(int, (user.get("beacon_end") or "21:00").split(":"))
    start_dt = now.replace(hour=start_h, minute=start_m, second=0, microsecond=0)
    end_dt = now.replace(hour=end_h, minute=end_m, second=0, microsecond=0)
    if end_dt <= start_dt:
        end_dt += timedelta(days=1)
    window = (end_dt - start_dt).total_seconds()
    if window <= 0 or count <= 0:
        return []
    rnd = random.Random(f"{user.get('user_id')}-{now.date().isoformat()}")
    bucket = window / count
    return [start_dt + timedelta(seconds=i * bucket + rnd.uniform(0, bucket)) for i in range(count)]

def _skill_beacon_due(user, now):
    """Пора ли слать напоминание с навыком — либо фиксированный интервал в
    минутах, либо N раз в день в случайные моменты (см. _skill_beacon_random_times)."""
    last_raw = user.get("skill_beacon_last_sent") or ""
    last_dt = None
    if last_raw:
        try:
            last_dt = datetime.fromisoformat(last_raw).astimezone(now.tzinfo)
        except Exception:
            pass

    if (user.get("skill_beacon_mode") or "interval") == "random":
        count = max(1, int(user.get("skill_beacon_daily_count") or 3))
        targets = _skill_beacon_random_times(user, now, count)
        if last_dt and last_dt.date() == now.date():
            targets = [t for t in targets if t > last_dt]
        return bool(targets) and now >= targets[0]

    interval_min = int(user.get("skill_beacon_interval") or 60)
    if last_dt is None:
        return True
    return (now - last_dt).total_seconds() >= interval_min * 60 - 30

async def send_skill_beacon(app, user):
    """Напоминания с навыками — независимый блок настроек: периодически
    предлагает короткую технику (см. "🎯 Типы маячка"), после которой сама
    же спрашивает про задачи дня (см. beacon_technique_done). Частота и
    вкл/выкл — отдельно от напоминаний по задачам, см. send_task_beacon."""
    try:
        uid = user["user_id"]
        if not int(user.get("skill_beacon_enabled") or 0): return
        tz = get_user_tz(user)
        now = datetime.now(tz)
        if not _in_beacon_hours(user, now): return
        if not _skill_beacon_due(user, now): return

        slot = next_beacon_slot(uid)
        if slot is None: return  # ни одна техника не включена

        # Если у техники есть анимация (см. SKILL_ANIMATIONS в 🧠 Навыки) —
        # присылаем её тоже, отдельным сообщением перед текстом, как и в
        # каталоге навыков. Раньше маячок слал только текст, даже для
        # техник вроде дыхания, для которых анимация — часть объяснения.
        skill_name = BEACON_TECHNIQUE_SKILL_NAMES.get(slot)
        animation_path = SKILL_ANIMATIONS.get(skill_name) if skill_name else None
        if animation_path:
            try:
                cached_id = _skill_animation_file_ids.get(skill_name)
                sent_anim = await app.bot.send_animation(chat_id=uid, animation=cached_id or open(animation_path, "rb"))
                if not cached_id and sent_anim.animation:
                    _skill_animation_file_ids[skill_name] = sent_anim.animation.file_id
            except Exception as e:
                print(f"Ошибка отправки анимации маячка {skill_name}: {e}")

        done_label = g(user["gender"], "✅ Сделал", "✅ Сделала")
        await app.bot.send_message(
            chat_id=uid,
            text=BEACON_TECHNIQUE_PROMPTS[slot],
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(done_label, callback_data="beacon_technique_done")],
                [InlineKeyboardButton("❓ Зачем это?", callback_data="why_beacon_technique")],
            ])
        )
        update_user(uid, skill_beacon_last_sent=now.isoformat())
    except Exception as e:
        print(f"Ошибка маячка навыков uid={user.get('user_id')}: {e}")

async def send_work_start_reminder(app, user):
    """Разовое напоминание «пора начинать» в момент, который человек сам
    назвал утром (см. morning_task_offer_yes) — не повторяющееся
    расписание, актуально только на сегодня."""
    try:
        uid = user["user_id"]
        wtime = user.get("work_start_time") or ""
        wdate = user.get("work_start_date") or ""
        if not wtime or not wdate: return

        tz = get_user_tz(user)
        now = datetime.now(tz)
        today_iso = now.date().isoformat()
        if wdate != today_iso: return
        if user.get("work_start_sent_date") == today_iso: return
        if now.strftime("%H:%M") < wtime: return

        _, morning, _ = get_today_context(user)
        focus = (morning or {}).get("focus", "")
        text = "🚪 *Пора начинать!*"
        if focus:
            text += f"\n\n🅰️ {md_escape(focus)}"
        await app.bot.send_message(
            chat_id=uid, text=text, parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("📋 Все задачи на сегодня", callback_data="go_tasks")]])
        )
        update_user(uid, work_start_sent_date=today_iso)
    except Exception as e:
        print(f"Ошибка напоминания о начале работы uid={user.get('user_id')}: {e}")


TASK_LABELS = {
    "focus": "Задача A",
    "b1":    "Задача B1",
    "b2":    "Задача B2",
    "c1":    "Задача C1",
    "c2":    "Задача C2",
    "c3":    "Задача C3",
}

# Короткая форма для кнопок "Выполнено" в 📋 Задачи — раньше там был сам
# текст задачи (обрезанный до 24 символов), но Telegram всё равно резал
# длинную подпись кнопки в произвольном месте, получалось нечитаемо.
SHORT_TASK_LABELS = {
    "focus": "A", "b1": "B1", "b2": "B2",
    "c1": "C1", "c2": "C2", "c3": "C3",
}

def _short_button_text(text, limit=28):
    """Сокращает текст задачи для кнопки, обрезая по границе слова и
    добавляя "…" — если отдать длинный текст как есть, Telegram сам режет
    кнопку посередине ("начало...конец"), и это нечитаемо (фидбек
    Виктории/Артёма). Обрезаем сами, по словам, чтобы остались первые —
    обычно главные — слова целиком, без обрыва на середине слова."""
    text = text.strip()
    if len(text) <= limit:
        return text
    cut = text[:limit].rsplit(" ", 1)[0].strip()
    if not cut:
        cut = text[:limit].strip()
    return cut + "…"

def _task_checkbox_rows(morning, done_set):
    """Строки-кнопки ▫️/✅ по каждой задаче A/B1/B2/C1/C2/C3 — общие для
    📋 Задачи (_tasks_text_and_kb) и для дневного чекина/маячка (midday_kb),
    чтобы отметка конкретной задачи работала одинаково в обоих местах, а не
    жила в двух независимых кусках кода, которые легко рассинхронизировать.
    callback_data (task_done_{key}) ведёт в тот же task_done_callback —
    тап засчитывается независимо от того, с какого экрана он сделан."""
    rows = []
    for key, icon in TASK_FIELDS:
        val = morning.get(key, "")
        if not val:
            continue
        mark = "✅" if key in done_set else "▫️"
        button_text = f"{mark} {SHORT_TASK_LABELS[key]}: {_short_button_text(val)}"
        rows.append([InlineKeyboardButton(button_text, callback_data=f"task_done_{key}")])
    return rows

def _tasks_text_and_kb(morning, done_set, gender):
    """Строит текст и клавиатуру задач с отметками выполнения, добавлением
    и правкой — без прохождения полного утреннего ритуала. См. фидбек
    Виктории (хотела добавить задачу днём, а бот предлагал пройти утро
    заново) и Анны (хотела доступ к задачам не только через ритуал).

    done_set — множество ключей TASK_FIELDS (focus/b1/b2/c1/c2/c3), а не
    отдельных "A/B1/.." меток — тот же формат, что использует вечерний
    блок и карточка дня, чтобы отметки, поставленные днём в этом меню,
    не терялись при вечернем ревью и наоборот.

    Строка задачи в тексте всегда показывает буквенную метку (A/B1/B2/C1/
    C2/C3), даже если задача уже выполнена — без ✅: галочка в самом тексте
    списка "что сделать" читается как "уже сделано" и сбивает с толку
    (фидбек Виктории). Выполненность вместо этого — чекбокс на самой
    кнопке-действии (▫️/✅), который можно тапнуть в обе стороны."""
    lines = []
    for key, icon in TASK_FIELDS:
        val = morning.get(key, "")
        if val:
            lines.append(f"{icon}: {md_escape(val)}")
    buttons = _task_checkbox_rows(morning, done_set)

    text = "📋 *Задачи на сегодня*\n\n" + ("\n".join(lines) if lines else "_задачи ещё не заданы — можно добавить прямо здесь_")
    # Одна кнопка входа вместо отдельной "✏️ Изменить" на каждой строке —
    # ведёт в последовательный проход по всем слотам (walk_tasks_start),
    # где на уже заполненных можно быстро "Пропустить" до нужной, а не
    # решать сразу по всем шести на одном экране.
    buttons.append([InlineKeyboardButton("✏️ Поставить/изменить задачи", callback_data="walk_tasks")])
    kb_rows = buttons + [
        [InlineKeyboardButton("📥 Список дел", callback_data="go_task_pool")],
        [InlineKeyboardButton(personalize("🆘 Застрял(а)?", gender), callback_data="mid_coach")],
        [InlineKeyboardButton("◀️ Меню", callback_data="go_menu")],
    ]
    return text, InlineKeyboardMarkup(kb_rows)

async def show_tasks(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Показать все задачи на сегодня — с возможностью добавить или
    поменять любую из них прямо здесь, не проходя весь утренний ритуал."""
    q = update.callback_query; await q.answer()
    clear_awaiting_flags(ctx, update)
    uid = q.from_user.id
    today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()
    morning = get_diary(uid, "morning", today)
    done_data = get_diary(uid, "tasks_done", today)
    done_set = set(done_data.get("done", []))
    text, kb = _tasks_text_and_kb(morning, done_set, get_user(uid)["gender"])
    if not morning:
        text += "\n\n_Утро ещё не заполнялось — можно поставить задачи прямо тут, или пройти полный утренний ритуал кнопкой ☀️ в меню._"
    await q.message.reply_text(text, parse_mode="Markdown", reply_markup=kb)

async def _offer_task_input(message, ctx, uid, key):
    """Если в «Списке дел» (пуле) уже что-то накоплено — сначала предлагаем
    выбрать готовую формулировку оттуда, а не сразу просить печатать текст.
    Приглашение явно разрешает и печатать текст сразу, минуя кнопки —
    поэтому awaiting_task_edit нужно взводить в обеих ветках, не только
    в ask_task_text (иначе такой текст улетал не туда, в роутер свободных
    сообщений)."""
    ctx.user_data["awaiting_task_edit"] = key
    pool = get_pool_tasks(uid)
    if pool:
        await message.reply_text(
            f"{TASK_LABELS.get(key, key)}\n\nМожешь выбрать из списка дел или написать свою:",
            reply_markup=pool_suggestions_kb(key, pool)
        )
    else:
        await ask_task_text(message, ctx, key)

async def edit_task_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Больше не выставляется новыми экранами (см. walk_tasks_start) —
    оставлена ради уже отправленных старых сообщений с кнопкой «✏️
    Изменить» на конкретном слоте, чтобы они не переставали работать."""
    q = update.callback_query; await q.answer()
    key = q.data.replace("edit_task_", "")
    clear_awaiting_flags(ctx, update)
    uid = q.from_user.id
    await _offer_task_input(q.message, ctx, uid, key)

async def add_next_task_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Больше не выставляется новыми экранами (см. walk_tasks_start) —
    оставлена ради уже отправленных старых сообщений с кнопкой «➕
    Добавить задачу», чтобы они не переставали работать."""
    q = update.callback_query; await q.answer()
    clear_awaiting_flags(ctx, update)
    uid = q.from_user.id
    today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()
    morning = get_diary(uid, "morning", today)
    key = next((k for k, _ in TASK_FIELDS if not morning.get(k)), None)
    if key is None:
        await q.message.reply_text("Все задачи на сегодня уже поставлены 🎉", reply_markup=menu_button_kb())
        return
    await _offer_task_input(q.message, ctx, uid, key)

def _next_task_key(key):
    keys = [k for k, _ in TASK_FIELDS]
    idx = keys.index(key)
    return keys[idx + 1] if idx + 1 < len(keys) else None

async def _walk_to_step(message, ctx, uid, key):
    """Один шаг последовательного прохода по задачам (A → B1 → B2 → C1 →
    C2 → C3, см. walk_tasks_start) — по просьбе Артёма: «когда ставишь/
    меняешь задачи, это должно происходить по одной». Пустой слот сразу
    предлагает ввести текст (как раньше add_next_task); заполненный —
    показывает текущий текст с «Пропустить»/«Поменять»/«Готово», чтобы
    можно было быстро долистать до нужной задачи, а не решать сразу
    по всем шести на одном экране."""
    # На случай, если где-то на экране ещё висит незакрытая кнопка другого
    # флоу (например «✏️ Изменить имя» из Настроек) — не даём её awaiting_*
    # флагу перехватить следующий текст, который тут явно ждёт от нас
    # ввод текста задачи.
    clear_awaiting_flags(ctx)
    if key is None:
        await message.reply_text("Прошлись по всем задачам ✅", reply_markup=menu_button_kb())
        return
    today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()
    morning = get_diary(uid, "morning", today)
    val = morning.get(key)
    if not val:
        ctx.user_data["task_walk"] = True
        await _offer_task_input(message, ctx, uid, key)
        return
    label = TASK_LABELS.get(key, key)
    await message.reply_text(
        f"{label}\n\n{md_escape(val)}",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("➡️ Пропустить", callback_data=f"walk_skip_{key}")],
            [InlineKeyboardButton("✏️ Поменять", callback_data=f"walk_edit_{key}")],
            [InlineKeyboardButton("✅ Готово", callback_data="walk_finish")],
        ])
    )

async def walk_tasks_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """«✏️ Поставить/изменить задачи» — единая точка входа вместо отдельной
    «✏️ Изменить» на каждой строке списка. Ведёт последовательно по всем
    шести слотам, см. _walk_to_step."""
    q = update.callback_query; await q.answer()
    clear_awaiting_flags(ctx, update)
    uid = q.from_user.id
    await _walk_to_step(q.message, ctx, uid, TASK_FIELDS[0][0])

async def walk_skip_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    key = q.data[len("walk_skip_"):]
    uid = q.from_user.id
    await _walk_to_step(q.message, ctx, uid, _next_task_key(key))

async def walk_edit_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    key = q.data[len("walk_edit_"):]
    uid = q.from_user.id
    clear_awaiting_flags(ctx, update)
    ctx.user_data["task_walk"] = True
    await _offer_task_input(q.message, ctx, uid, key)

async def walk_finish_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    clear_awaiting_flags(ctx, update)
    uid = q.from_user.id
    today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()
    morning = get_diary(uid, "morning", today)
    done_set = set(get_diary(uid, "tasks_done", today).get("done", []))
    text, kb = _tasks_text_and_kb(morning, done_set, get_user(uid)["gender"])
    await q.message.reply_text(text, parse_mode="Markdown", reply_markup=kb)

async def ask_task_text(message, ctx, key):
    ctx.user_data["awaiting_task_edit"] = key
    label = TASK_LABELS.get(key, key)
    await message.reply_text(
        f"{label}\n\nВведи текст задачи:",
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Отмена", callback_data="go_tasks")]])
    )

def pool_suggestions_kb(key, pool, offset=0, limit=3):
    chunk = pool[offset:offset + limit]
    rows = [[InlineKeyboardButton(item["text"][:40], callback_data=f"pooluse_{key}_{item['id']}")] for item in chunk]
    if offset + limit < len(pool):
        rows.append([InlineKeyboardButton("Показать ещё", callback_data=f"poolmore_{key}_{offset + limit}")])
    rows.append([InlineKeyboardButton("✍️ Напишу свою", callback_data=f"poolwrite_{key}")])
    rows.append([InlineKeyboardButton("Отмена", callback_data="go_tasks")])
    return InlineKeyboardMarkup(rows)

async def pool_show_more(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    key, offset_s = q.data[len("poolmore_"):].rsplit("_", 1)
    pool = get_pool_tasks(q.from_user.id)
    await q.message.edit_reply_markup(reply_markup=pool_suggestions_kb(key, pool, offset=int(offset_s)))

async def pool_write_own(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    key = q.data.replace("poolwrite_", "")
    await ask_task_text(q.message, ctx, key)

async def add_pool_and_reply(message, uid, items):
    """Общая логика и для явного экрана «📥 Список дел», и для роутера
    свободного текста (route_free_text). items — одна строка или список
    строк: одним сообщением можно закинуть сразу несколько дел (например
    списком, по одному на строку), каждое становится отдельным пунктом,
    а не одним пунктом со всем текстом целиком."""
    if isinstance(items, str):
        items = [items]
    items = [t.strip() for t in items if t and t.strip()]
    for text in items:
        add_pool_task(uid, text)
    pool = get_pool_tasks(uid)
    prefix = "✅ Добавил в список дел.\n\n" if len(items) <= 1 else f"✅ Добавил {len(items)} дел в список.\n\n"
    await message.reply_text(
        prefix + task_pool_text(pool),
        parse_mode="Markdown", reply_markup=task_pool_kb(pool)
    )

async def create_reminder_and_reply(message, uid, remind_at_key, rem_text, recur=""):
    """Общая логика и для явного экрана «⏰ Напоминания», и для роутера
    свободного текста (route_free_text)."""
    add_reminder(uid, rem_text, remind_at_key, recur)
    when = datetime.fromisoformat(remind_at_key)
    reminders = get_reminders(uid)
    text, kb = reminders_text_and_kb(reminders)
    label = recur_label(remind_at_key, recur)
    when_str = f"{label}, начиная с {when.strftime('%d.%m')}, в {when.strftime('%H:%M')}" if label \
        else f"{when.strftime('%d.%m в %H:%M')}"
    await message.reply_text(
        f"✅ Напомню {when_str}: {md_escape(rem_text)}\n\n" + text,
        parse_mode="Markdown", reply_markup=kb
    )

def _match_by_text(items, query):
    """Нестрогий поиск по подстроке для удаления по свободной фразе — items
    это список словарей с ключом "text" (напоминания или дела из пула)."""
    q = (query or "").strip().lower()
    if not q:
        return []
    return [it for it in items if q in it["text"].lower() or it["text"].lower() in q]

async def handle_delete_reminder_intent(message, uid, query):
    """Удаление напоминания по свободной фразе. При точном одном совпадении
    удаляет сразу; если совпадений 0 или больше 1 — не гадает, а переспрашивает,
    показывая максимум пару похожих кандидатов (не весь список — иначе тот же
    паралич выбора, от которого уже лечили экран задач) — так попросил Артём."""
    items = get_reminders(uid)
    if not items:
        await message.reply_text("Активных напоминаний нет.", reply_markup=menu_button_kb())
        return
    matches = _match_by_text(items, query)
    if len(matches) == 1:
        target = matches[0]
        cancel_reminder(uid, target["id"])
        remaining = get_reminders(uid)
        text, kb = reminders_text_and_kb(remaining)
        await message.reply_text(f"✅ Удалил: {md_escape(target['text'])}\n\n" + text, parse_mode="Markdown", reply_markup=kb)
        return
    candidates = (matches or items)[:2]
    text, kb = reminders_text_and_kb(candidates)
    await message.reply_text("Не понял, какое именно — вот похожие, выбери 🗑:\n\n" + text, parse_mode="Markdown", reply_markup=kb)

async def handle_delete_pool_intent(message, uid, query):
    """Удаление дела из списка дел по свободной фразе — та же логика
    "переспрашивать при неоднозначности, максимум пара кандидатов", что и
    у напоминаний."""
    items = get_pool_tasks(uid)
    if not items:
        await message.reply_text("Список дел пуст.", reply_markup=menu_button_kb())
        return
    matches = _match_by_text(items, query)
    if len(matches) == 1:
        target = matches[0]
        delete_pool_task(uid, target["id"])
        pool = get_pool_tasks(uid)
        await message.reply_text(
            f"✅ Удалил из списка дел: {md_escape(target['text'])}\n\n" + task_pool_text(pool),
            parse_mode="Markdown", reply_markup=task_pool_kb(pool)
        )
        return
    candidates = (matches or items)[:2]
    await send_pool_delete_menu(message, uid, items=candidates)

async def apply_task_edit(message, ctx, uid, key, text, pool_item_id=None):
    """Сохраняет текст задачи в утренний дневник — общая логика и для
    свободного ввода (handle_text), и для выбора готового дела из пула.

    awaiting_task_edit чистим здесь безусловно: путь через handle_text уже
    сам его снимает перед вызовом, а путь через выбор пункта из пула
    (pool_use_item) — нет, так что флаг оставался висеть и перехватывал
    следующее не связанное с задачами сообщение пользователя.

    pool_item_id (по фидбеку Виктории) — если задача пришла из «Список
    дел», запоминаем связь со слотом, а не удаляем пункт сразу при выборе:
    он пропадёт из пула только когда эту задачу реально отметят ✅ (см.
    task_done_callback). Если слот потом перезаписывают — вручную набранным
    текстом или другим пунктом пула — старая связь тут же затирается,
    иначе отметка "выполнено" по новому тексту задачи удалила бы чужой,
    больше не связанный с ней пункт списка дел."""
    ctx.user_data.pop("awaiting_task_edit", None)
    today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()
    morning = get_diary(uid, "morning", today)
    was_filled = bool(morning.get(key))
    morning[key] = text
    link_key = f"_pool_link_{key}"
    if pool_item_id is not None:
        morning[link_key] = pool_item_id
    else:
        morning.pop(link_key, None)
    save_diary(uid, "morning", morning, for_date=today)
    if was_filled:
        # Текст задачи поменялся — старая отметка "выполнено" больше не
        # про эту задачу (иначе новая задача выглядела бы уже сделанной).
        done_data = get_diary(uid, "tasks_done", today)
        done_list = [k for k in done_data.get("done", []) if k != key]
        if len(done_list) != len(done_data.get("done", [])):
            save_diary(uid, "tasks_done", {"done": done_list}, for_date=today)
    done_data2 = get_diary(uid, "tasks_done", today)
    done_set = set(done_data2.get("done", []))
    out_text, kb = _tasks_text_and_kb(morning, done_set, get_user(uid)["gender"])
    prefix = "✅ Обновил.\n\n" if was_filled else "✅ Добавил.\n\n"

    if ctx.user_data.pop("task_walk", False):
        # Идём последовательным проходом по слотам (walk_tasks_start) —
        # после сохранения сами переходим к следующему, а не возвращаем
        # на полный список с решением "что дальше" за пользователем.
        await message.reply_text(prefix + out_text, parse_mode="Markdown")
        await _walk_to_step(message, ctx, uid, _next_task_key(key))
        return

    await message.reply_text(prefix + out_text, parse_mode="Markdown", reply_markup=kb)

async def pool_use_item(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    key, id_s = q.data[len("pooluse_"):].rsplit("_", 1)
    uid = q.from_user.id
    pool = get_pool_tasks(uid)
    item = next((t for t in pool if t["id"] == int(id_s)), None)
    if item is None:
        await q.message.reply_text("Это дело уже не в списке — выбери другое или напиши текст.")
        return
    await apply_task_edit(q.message, ctx, uid, key, item["text"], pool_item_id=item["id"])

def task_pool_kb(pool):
    rows = []
    if pool:
        rows.append([InlineKeyboardButton("🗑 Удалить дело", callback_data="pool_del_menu")])
    rows.append([InlineKeyboardButton("✏️ Добавить дело", callback_data="pool_add")])
    rows.append([InlineKeyboardButton("◀️ К задачам", callback_data="go_tasks")])
    return InlineKeyboardMarkup(rows)

def task_pool_text(pool):
    if not pool:
        return ("📥 *Список дел*\n\n_Пока пусто — сюда можно скидывать любые дела, "
                "не только на сегодня, а потом выбирать из них при постановке A/B/C._")
    lines = [f"{i+1}. {md_escape(t['text'])}" for i, t in enumerate(pool)]
    return "📥 *Список дел*\n\n" + "\n".join(lines)

