async def task_done_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Чекбокс "▫️/✅" на задаче — тапается в обе стороны (можно снять
    отметку, если поставил(а) по ошибке), в отличие от прежней кнопки
    "Отметить", которая просто исчезала после первого тапа."""
    q = update.callback_query; await q.answer()
    clear_awaiting_flags(ctx, update)
    uid = q.from_user.id
    key = q.data.replace("task_done_", "")  # focus, b1, b2, c1, c2, c3
    today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()

    done_data = get_diary(uid, "tasks_done", today)
    done_list = done_data.get("done", [])
    just_completed = key not in done_list
    if just_completed:
        done_list.append(key)
    else:
        done_list.remove(key)
    save_diary(uid, "tasks_done", {"done": done_list}, for_date=today)

    morning = get_diary(uid, "morning", today)
    # Если задача пришла из «Список дел» (см. apply_task_edit/pool_use_item),
    # пункт пула пропадает из списка только сейчас — в момент, когда задачу
    # реально отметили выполненной, а не сразу при выборе формулировки.
    if just_completed:
        link_key = f"_pool_link_{key}"
        linked_pool_id = morning.pop(link_key, None)
        if linked_pool_id is not None:
            delete_pool_task(uid, linked_pool_id)
            save_diary(uid, "morning", morning, for_date=today)
    done_set = set(done_list)
    text, kb = _tasks_text_and_kb(morning, done_set, get_user(uid)["gender"])

    all_keys = {k for k, _ in TASK_FIELDS if morning.get(k)}
    if all_keys and all_keys <= done_set:
        text += "\n\n🎉 *Все задачи выполнены! Отличный день!*"

    try:
        await q.message.edit_text(text, parse_mode="Markdown", reply_markup=kb)
    except Exception:
        await q.message.reply_text(text, parse_mode="Markdown", reply_markup=kb)


# ── REMINDERS ─────────────────────────────────────────────────────────────
def reminders_text_and_kb(reminders):
    if not reminders:
        text = "⏰ *Напоминания*\n\n_Активных напоминаний нет — можно поставить одно свободной фразой._"
    else:
        lines = []
        for r in reminders:
            try:
                when_str = datetime.fromisoformat(r["remind_at"]).strftime("%d.%m %H:%M")
            except Exception:
                when_str = r["remind_at"]
            label = recur_label(r["remind_at"], r.get("recur") or "")
            recur_suffix = f" 🔁 {label}" if label else ""
            lines.append(f"🔹 {when_str}{recur_suffix} — {md_escape(r['text'])}")
        text = "⏰ *Напоминания*\n\n" + "\n".join(lines)
    rows = [
        [InlineKeyboardButton(f"✏️ {r['text'][:25]}", callback_data=f"remedit_{r['id']}"),
         InlineKeyboardButton("🗑", callback_data=f"remdel_{r['id']}")]
        for r in reminders
    ]
    rows.append([InlineKeyboardButton("➕ Новое напоминание", callback_data="rem_add")])
    rows.append([InlineKeyboardButton("◀️ Меню", callback_data="go_menu")])
    return text, InlineKeyboardMarkup(rows)

