async def handle_text(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    if ctx.user_data.get("awaiting_time"):
        ctx.user_data["awaiting_time"] = False
        block = ctx.user_data.get("setting_notif", "")
        text = update.message.text.strip()
        # Validate HH:MM format
        if re.match(r"^([01]?\d|2[0-3]):[0-5]\d$", text):
            # Регулярка выше намеренно разрешает час без ведущего нуля
            # ("9:30"), но notif_morning/midday/evening потом сравниваются
            # с now.strftime("%H:%M") ЛЕКСИКОГРАФИЧЕСКИ ("14:00" >= "9:30"
            # даёт False) — без нормализации к "09:30" уведомление на такое
            # время почти никогда не срабатывает. Приводим к HH:MM сразу.
            h, m = map(int, text.split(":"))
            text = f"{h:02d}:{m:02d}"
            if block in ("beacon_start", "beacon_end"):
                update_user(uid, **{block: text})
                beacon_labels = {"beacon_start": "🌅 Начало", "beacon_end": "🌇 Конец"}
                await update.message.reply_text(
                    f"{beacon_labels.get(block,'')} рабочих часов маячка установлен на *{text}* ✅",
                    parse_mode="Markdown",
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("◀️ Настройки", callback_data="go_settings")]])
                )
            else:
                field = f"notif_{block}"
                update_user(uid, **{field: text})
                update_user(uid, notif_enabled=1)
                # check_notifications шлёт как только "now >= время И сегодня
                # ещё не отправлено" (чтобы переживать пропущенные тики) — если
                # новое время уже прошло сегодня, это без правки прислало бы
                # уведомление немедленно, "задним числом". Помечаем сегодняшний
                # день как уже отправленный, чтобы новое время подхватилось с завтра.
                user_tz = get_user_tz(get_user(uid))
                now_tz = datetime.now(user_tz)
                new_h, new_m = map(int, text.split(":"))
                if (new_h, new_m) <= (now_tz.hour, now_tz.minute):
                    update_user(uid, **{f"{block}_sent_date": now_tz.date().isoformat()})
                labels = {"morning": "☀️ Утро", "midday": "☕ День", "evening": "🌙 Вечер"}
                await update.message.reply_text(
                    f"{labels.get(block,'')} уведомление установлено на *{text}* ✅\n\nУведомления включены.",
                    parse_mode="Markdown",
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("◀️ Настройки", callback_data="go_settings")]])
                )
        else:
            await update.message.reply_text(
                "Неверный формат. Введи время в формате ЧЧ:ММ, например: `08:30`",
                parse_mode="Markdown"
            )
            ctx.user_data["awaiting_time"] = True
    elif ctx.user_data.get("awaiting_name"):
        ctx.user_data["awaiting_name"] = False
        new_name = update.message.text.strip()
        if not new_name:
            ctx.user_data["awaiting_name"] = True
            await update.message.reply_text("Имя не может быть пустым, напиши ещё раз:")
        elif len(new_name) > 30:
            ctx.user_data["awaiting_name"] = True
            await update.message.reply_text("Имя слишком длинное, напиши покороче:")
        else:
            update_user(uid, name=new_name)
            await update.message.reply_text(
                f"✅ Готово, буду звать тебя *{md_escape(new_name)}*.",
                parse_mode="Markdown", reply_markup=menu_button_kb()
            )
    elif ctx.user_data.get("awaiting_buddy"):
        ctx.user_data["awaiting_buddy"] = False
        bname = update.message.text.strip()
        update_user(uid, buddy_name=bname)
        await update.message.reply_text(
            f"👥 *Бадди добавлен: {md_escape(bname)}*\n\nВ 13:00 бот предложит обратиться к нему при трудностях.",
            parse_mode="Markdown", reply_markup=menu_button_kb()
        )
    elif ctx.user_data.get("awaiting_city"):
        ctx.user_data["awaiting_city"] = False
        from_settings = ctx.user_data.pop("city_from_settings", False)
        city = update.message.text.strip()
        update_user(uid, city=city)
        # Определяем таймзону по городу
        thinking = await update.message.reply_text(f"📍 Ищу {city}...")
        tz_name = await get_timezone_from_city(city)
        if tz_name:
            update_user(uid, timezone=tz_name)
            # Показываем offset для удобства
            tz_obj = pytz.timezone(tz_name)
            offset = datetime.now(tz_obj).strftime("%z")
            offset_str = f"UTC{offset[:3]}:{offset[3:]}" if len(offset) == 5 else offset
            await thinking.edit_text(
                f"📍 *{md_escape(city)}* — записал!\n"
                f"🕐 Твоя таймзона: *{tz_name}* ({offset_str})\n\n"
                f"Уведомления будут приходить по времени твоего города.",
                parse_mode="Markdown"
            )
        else:
            await thinking.edit_text(
                f"📍 {city} — записал!\n\n"
                f"⚠️ Не удалось определить таймзону автоматически — "
                f"уведомления будут по умолчанию ({USER_TIMEZONE}). "
                f"Можно изменить в ⚙️ Настройки позже."
            )
        if from_settings:
            text, kb = _settings_text_and_kb(get_user(uid))
            await update.message.reply_text(text, parse_mode="Markdown", reply_markup=kb)
            return
        # Показываем настройку уведомлений
        await update.message.reply_text(
            "🔔 *Последний шаг — уведомления*\n\n"
            "Бот пишет три раза в день: утром, днём и вечером "
            "(по умолчанию: 09:00 · 13:00 · 21:00) — они уже включены.\n\n"
            "Если не хочешь их получать, можешь отключить.",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("✅ Оставить включёнными", callback_data="onboard_notif_on")],
                [InlineKeyboardButton("🔕 Отключить", callback_data="onboard_notif_skip")],
            ])
        )
        return
    elif (ru := get_user(uid)) and ru.get("research_awaiting") and str(ru.get("research_awaiting")) != "0":
        user = ru
        awaiting = str(user.get("research_awaiting", ""))
        text = update.message.text.strip()
        # format: "DAY_open" или "DAY_open:вопрос", напр. "3_open:Что было полезным?"
        day_part, _, embedded_q = awaiting.partition(":")
        day = int(day_part.split("_")[0]) if "_" in day_part else 0
        if day:
            save_research(uid, day, f"day{day}_text", text)
            update_user(uid, research_awaiting=0)
            user = get_user(uid)
            if NOTIFY_USER_ID:
                q_text = embedded_q or RESEARCH_QUESTION_LABELS.get(f"day{day}_text", "")
                try:
                    await ctx.bot.send_message(
                        NOTIFY_USER_ID,
                        f"🔬 *Исследование день {day} от {md_escape(user['name']) or uid}:*\n\n"
                        f"_{q_text}_\n{md_escape(text)}",
                        parse_mode="Markdown"
                    )
                except Exception as e:
                    print(f"Не удалось переслать ответ исследования: {e}")
            await update.message.reply_text(
                "Спасибо! Твой ответ очень важен 🙏",
                reply_markup=menu_button_kb()
            )
        return
    elif ctx.user_data.get("awaiting_feedback"):
        ctx.user_data["awaiting_feedback"] = False
        text = update.message.text.strip()
        save_feedback(uid, text)
        user = get_user(uid)
        if NOTIFY_USER_ID:
            try:
                await ctx.bot.send_message(
                    NOTIFY_USER_ID,
                    f"💬 *Обратная связь от {md_escape(user['name']) or uid}:*\n\n{md_escape(text)}",
                    parse_mode="Markdown"
                )
            except Exception as e:
                print(f"Не удалось переслать обратную связь: {e}")
        await update.message.reply_text(
            "Спасибо! Идея записана 🙏",
            reply_markup=menu_button_kb()
        )
    elif ctx.user_data.get("awaiting_promo_code"):
        ctx.user_data["awaiting_promo_code"] = False
        code = update.message.text.strip().upper()
        ok, msg = redeem_promo_code(uid, code)
        await update.message.reply_text(
            ("✅ " if ok else "⚠️ ") + msg,
            reply_markup=menu_button_kb()
        )
    elif ctx.user_data.get("awaiting_task_edit"):
        key = ctx.user_data.pop("awaiting_task_edit")
        await apply_task_edit(update.message, ctx, uid, key, update.message.text.strip())
    elif ctx.user_data.get("awaiting_pool_add"):
        ctx.user_data["awaiting_pool_add"] = False
        # Каждая непустая строка — отдельное дело, а не один пункт со всем
        # вставленным текстом целиком (удобно, если вставляешь список).
        items = update.message.text.strip().split("\n")
        await add_pool_and_reply(update.message, uid, items)
    elif ctx.user_data.get("awaiting_reminder_add"):
        ctx.user_data["awaiting_reminder_add"] = False
        now_dt = datetime.now(get_user_tz(get_user(uid)))
        parsed = await parse_reminder_request(update.message.text.strip(), now_dt)
        if parsed is None:
            ctx.user_data["awaiting_reminder_add"] = True
            await update.message.reply_text(
                "Не получилось понять, когда напомнить. Попробуй ещё раз, например:\n"
                "`через 20 минут проверить почту`",
                parse_mode="Markdown"
            )
        else:
            remind_at_key, rem_text, recur = parsed
            await create_reminder_and_reply(update.message, uid, remind_at_key, rem_text, recur)
    elif ctx.user_data.get("awaiting_reminder_edit"):
        rem_id = ctx.user_data.pop("awaiting_reminder_edit")
        now_dt = datetime.now(get_user_tz(get_user(uid)))
        parsed = await parse_reminder_request(update.message.text.strip(), now_dt)
        if parsed is None:
            ctx.user_data["awaiting_reminder_edit"] = rem_id
            await update.message.reply_text(
                "Не получилось понять, когда напомнить. Попробуй ещё раз, например:\n"
                "`через 20 минут проверить почту`",
                parse_mode="Markdown"
            )
        else:
            remind_at_key, rem_text, recur = parsed
            # Если новая фраза не упоминает повтор явно ("перенеси на 20:00"
            # для напоминания, которое и так было "каждый день") — не молча
            # понижаем его до разового. Модель просто не увидела повтор в
            # этой фразе, это не значит, что пользователь хочет его убрать.
            if not recur:
                existing_rem = get_reminder(uid, rem_id)
                if existing_rem:
                    recur = existing_rem.get("recur") or ""
            update_reminder(uid, rem_id, rem_text, remind_at_key, recur)
            when = datetime.fromisoformat(remind_at_key)
            reminders = get_reminders(uid)
            text, kb = reminders_text_and_kb(reminders)
            label = recur_label(remind_at_key, recur)
            when_str = f"{label}, начиная с {when.strftime('%d.%m')}, в {when.strftime('%H:%M')}" if label \
                else f"{when.strftime('%d.%m в %H:%M')}"
            await update.message.reply_text(
                f"✅ Изменил: {md_escape(rem_text)} — {when_str}\n\n" + text,
                parse_mode="Markdown", reply_markup=kb
            )
    elif ctx.user_data.get("awaiting_work_start"):
        ctx.user_data["awaiting_work_start"] = False
        text = update.message.text.strip()
        if re.match(r"^([01]?\d|2[0-3]):[0-5]\d$", text):
            # Нормализация к HH:MM — см. аналогичный комментарий у awaiting_time
            # выше: send_work_start_reminder сравнивает это лексикографически.
            h, m = map(int, text.split(":"))
            text = f"{h:02d}:{m:02d}"
            today = datetime.now(get_user_tz(get_user(uid))).date().isoformat()
            update_user(uid, work_start_time=text, work_start_date=today, work_start_sent_date="")
            await update.message.reply_text(
                f"🚪 Хорошо — в *{text}* пришлю напоминание с задачами.",
                parse_mode="Markdown", reply_markup=menu_button_kb()
            )
        else:
            await update.message.reply_text(
                "Неверный формат. Введи время в формате ЧЧ:ММ, например: `10:00`",
                parse_mode="Markdown"
            )
            ctx.user_data["awaiting_work_start"] = True
    elif ctx.user_data.get("admin_msg_target"):
        target_id = ctx.user_data.pop("admin_msg_target")
        name = ctx.user_data.pop("admin_msg_name", str(target_id))
        text = update.message.text.strip()
        try:
            await ctx.bot.send_message(target_id, text)
            await update.message.reply_text(f"✅ Отправлено {name}.")
        except Exception as e:
            await update.message.reply_text(f"❌ Не удалось: `{e}`", parse_mode="Markdown")
    elif ctx.user_data.get("coach_mode"):
        await send_coach(update.message, update.message.text, uid, ctx)
    else:
        # Свободный текст вне какого-либо раздела — вместо пересылки
        # администратору бот сам разбирает намерение (см. classify_free_text):
        # напоминание, дело в список дел, или разговор/вопрос — с коучем.
        text = update.message.text.strip()
        now_dt = datetime.now(get_user_tz(get_user(uid)))
        routed = await classify_free_text(text, now_dt)
        intent = routed.get("intent")
        if intent == "reminder":
            await create_reminder_and_reply(update.message, uid, routed["remind_at"], routed.get("text") or text, routed.get("recur") or "")
        elif intent == "add_pool":
            await add_pool_and_reply(update.message, uid, routed.get("items") or [text])
        elif intent == "delete" and routed.get("target") == "reminder":
            await handle_delete_reminder_intent(update.message, uid, routed.get("query") or text)
        elif intent == "delete" and routed.get("target") == "pool":
            await handle_delete_pool_intent(update.message, uid, routed.get("query") or text)
        elif intent == "edit_reminder":
            await handle_edit_reminder_intent(update.message, ctx, uid, routed.get("query") or text)
        else:
            ctx.user_data["coach_mode"] = True
            await send_coach(update.message, text, uid, ctx)

# ── ABOUT ──────────────────────────────────────────────────────────────────
# ── FOCUS / POMODORO ───────────────────────────────────────────────────────
async def go_focus(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    clear_awaiting_flags(ctx, update)
    uid = q.from_user.id
    user = get_user(uid)

    # Если таймер уже активен — показать статус
    if str(user.get("focus_active", "0")) == "1" and user.get("focus_end_time"):
        try:
            end_dt = datetime.fromisoformat(user["focus_end_time"])
            tz = get_user_tz(user)
            now = datetime.now(tz)
            end_dt_tz = end_dt.astimezone(tz)
            remaining = int((end_dt_tz - now).total_seconds() / 60)
            if remaining > 0:
                await q.message.reply_text(
                    f"🍅 *Таймер уже идёт!*\n\n"
                    f"Осталось примерно *{remaining} мин* (до {end_dt_tz.strftime('%H:%M')}).\n\n"
                    f"Не отвлекайся — я напишу когда время выйдет 🔕",
                    parse_mode="Markdown",
                    reply_markup=InlineKeyboardMarkup([
                        [InlineKeyboardButton("⏹ Остановить", callback_data="focus_stop")],
                        [InlineKeyboardButton("◀️ Меню", callback_data="go_menu")],
                    ])
                )
                return
        except Exception:
            pass

    # Считаем сколько минут в фокусе сегодня
    today, morning_data, done_set = get_today_context(user)
    mins_today = int(user.get("focus_minutes_today", 0)) if user.get("focus_date") == today else 0
    current_task = next_undone_task(morning_data, done_set)
    task_hint = f"\n\n📌 Твоя задача: *{current_task}*" if current_task else ""

    stats_hint = f"\n\n⏱ Сегодня в фокусе: *{mins_today} мин*" if mins_today > 0 else ""

    await q.message.reply_text(
        f"🍅 *Фокус-режим*\n\n"
        f"📝 *Перед стартом:* возьми листок бумаги и положи рядом.\n"
        f"Это «бумажка гениальных мыслей» — когда во время работы придёт посторонняя идея или мысль, просто запиши её и сразу возвращайся к задаче. Не нужно ничего обдумывать прямо сейчас. Так мозг отпускает мысль и не тратит силы держать её в голове.\n\n"
        f"На сколько минут работаем?{task_hint}{stats_hint}",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("5 мин", callback_data="focus_start_5"),
             InlineKeyboardButton("10 мин", callback_data="focus_start_10"),
             InlineKeyboardButton("15 мин", callback_data="focus_start_15")],
            [InlineKeyboardButton("25 мин", callback_data="focus_start_25"),
             InlineKeyboardButton("30 мин", callback_data="focus_start_30"),
             InlineKeyboardButton("45 мин", callback_data="focus_start_45")],
            [InlineKeyboardButton("60 мин", callback_data="focus_start_60"),
             InlineKeyboardButton("90 мин", callback_data="focus_start_90")],
            [InlineKeyboardButton("◀️ Меню", callback_data="go_menu")],
        ])
    )

async def focus_start_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    minutes = int(q.data.split("_")[2])

    user = get_user(uid)
    tz = get_user_tz(user)
    now = datetime.now(tz)

    # Кнопки запуска таймера не одноразовые — если уже идёт другой таймер
    # (например нажали кнопку из старого, ещё не убранного сообщения
    # /go_focus, пока свежий таймер уже тикает), не перезаписываем его молча.
    if str(user.get("focus_active", "0")) == "1" and user.get("focus_end_time"):
        try:
            active_end = datetime.fromisoformat(user["focus_end_time"]).astimezone(tz)
            if active_end > now:
                await q.message.reply_text(
                    f"🍅 Таймер уже идёт — до *{active_end.strftime('%H:%M')}*. Эта кнопка устарела.",
                    parse_mode="Markdown"
                )
                return
        except Exception:
            pass

    end_dt = now + timedelta(minutes=minutes)

    # Обновляем DB
    update_user(uid,
        focus_active=1,
        focus_end_time=end_dt.isoformat(),
        focus_duration=minutes,
    )

    end_str = end_dt.strftime("%H:%M")

    _, morning_data, done_set = get_today_context(user)
    current_task = next_undone_task(morning_data, done_set)
    task_hint = f"\n📌 Задача: *{current_task}*" if current_task else ""

    await q.message.reply_text(
        f"🍅 *Таймер запущен на {minutes} мин*\n\n"
        f"Конец в *{end_str}*.{task_hint}\n\n"
        f"Удачи — не отвлекайся 🔕\n"
        f"_Я напишу когда время выйдет._",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("⏹ Остановить", callback_data="focus_stop")],
        ])
    )

async def focus_stop_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    user = get_user(uid)
    tz = get_user_tz(user)
    now = datetime.now(tz)

    # Считаем сколько реально успел(а) отработать до досрочной остановки:
    # start = end_time - запланированная длительность, worked = now - start
    worked_mins = 0
    if user.get("focus_end_time") and str(user.get("focus_active", "0")) == "1":
        try:
            end_dt = datetime.fromisoformat(user["focus_end_time"]).astimezone(tz)
            duration = int(user.get("focus_duration") or 0)
            start_dt = end_dt - timedelta(minutes=duration)
            worked_mins = max(0, min(duration, int((now - start_dt).total_seconds() / 60)))
        except Exception:
            worked_mins = 0

    today = now.date().isoformat()
    prev_mins = int(user.get("focus_minutes_today", 0)) if user.get("focus_date") == today else 0
    mins_today = prev_mins + worked_mins
    update_user(uid, focus_active=0, focus_end_time="", focus_minutes_today=mins_today, focus_date=today)

    worked_note = f" — {worked_mins} мин в фокусе" if worked_mins else ""
    await q.message.reply_text(
        f"⏹ *Таймер остановлен*{worked_note}\n\n"
        f"Сегодня в фокусе: *{mins_today} мин*\n\n"
        f"Хочешь начать новый раунд?",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🍅 Новый раунд", callback_data="go_focus")],
            [InlineKeyboardButton("◀️ Меню", callback_data="go_menu")],
        ])
    )

async def send_focus_end(app, uid: int, minutes: int, expected_end_time: str):
    """Вызывается из check_notifications когда таймер истёк.

    expected_end_time — focus_end_time из снапшота пользователя, взятого в
    начале текущего тика check_notifications; между этим снапшотом и сюда
    проходит время (await на другие уведомления того же пользователя), за
    которое человек мог сам остановить таймер (focus_stop_callback) или
    запустить новый (focus_start_callback). Без сверки со свежим значением
    из БД это может задвоить минуты поверх того, что уже посчитал
    focus_stop_callback, либо молча погасить только что запущенный новый
    раунд."""
    try:
        user = get_user(uid)
        if str(user.get("focus_active", "0")) != "1" or user.get("focus_end_time") != expected_end_time:
            return  # таймер уже остановлен или перезапущен — этот тик устарел
        tz = get_user_tz(user)
        today = datetime.now(tz).date().isoformat()
        prev_mins = int(user.get("focus_minutes_today", 0)) if user.get("focus_date") == today else 0
        new_mins = prev_mins + minutes
        update_user(uid, focus_active=0, focus_end_time="", focus_minutes_today=new_mins, focus_date=today)

        await app.bot.send_message(
            chat_id=uid,
            text=(
                f"⏰ *Время вышло! {minutes} минут в фокусе — отлично!*\n\n"
                f"Сделай перерыв 5 минут: встань, выпей воды, отойди от экрана.\n\n"
                f"Сегодня в фокусе: *{new_mins} мин* 🎯"
            ),
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🍅 Ещё раунд", callback_data="go_focus")],
                [InlineKeyboardButton("✅ Хватит на сегодня", callback_data="go_menu")],
            ])
        )
    except Exception as e:
        print(f"Ошибка send_focus_end: {e}")


# ── RESEARCH QUESTIONS ─────────────────────────────────────────────────────
# Человекочитаемый текст вопроса по ключу question из таблицы research —
# без этого админу приходил только день и ответ, без понимания на что он.
RESEARCH_OPEN_Q_DAY3_LOW = "Что не получилось или что было неудобно?"
RESEARCH_OPEN_Q_DAY3_OK  = "Что было самым полезным за эти 3 дня?"
RESEARCH_OPEN_Q_DAY7     = "Что мешало использовать бота на этой неделе?"
RESEARCH_OPEN_Q_DAY14    = "Что стоит упростить или убрать в боте?"

RESEARCH_QUESTION_LABELS = {
    "day3_rating":  "Насколько полезен бот через 3 дня? (оценка 1-5)",
    "day3_text":    f"{RESEARCH_OPEN_Q_DAY3_OK} / {RESEARCH_OPEN_Q_DAY3_LOW}",
    "day7_rating":  "Был ли момент когда подумал(а) «о, это работает»?",
    "day7_text":    RESEARCH_OPEN_Q_DAY7,
    "day14_rating": "Насколько вероятно порекомендуешь бота другу с СДВГ? (0-10)",
    "day14_text":   RESEARCH_OPEN_Q_DAY14,
    "day30_rating": "Если бот перестанет работать — как ты к этому отнесёшься?",
}

def save_research(uid, day, question, answer):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("INSERT INTO research(user_id,day,question,answer,created) VALUES(?,?,?,?,?)",
              (uid, day, question, answer, datetime.now().isoformat()))
    conn.commit(); conn.close()

async def send_research_question(app, uid, day):
    """Отправить исследовательский вопрос по дню с момента регистрации."""
    user = get_user(uid)
    name = md_escape(user.get("name", ""))
    research_done = user.get("research_done") or ""

    if str(day) in research_done.split(","): return  # уже ответил

    if day == 3:
        await app.bot.send_message(
            chat_id=uid,
            text=(
                f"🔬 *{name}, короткий вопрос!*\n\n"
                f"Ты используешь бота уже 3 дня. Как ощущения?\n\n"
                f"Оцени насколько бот полезен прямо сейчас:"
            ),
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("1 😕", callback_data="research_3_1"),
                 InlineKeyboardButton("2 😐", callback_data="research_3_2"),
                 InlineKeyboardButton("3 🙂", callback_data="research_3_3"),
                 InlineKeyboardButton("4 😊", callback_data="research_3_4"),
                 InlineKeyboardButton("5 🤩", callback_data="research_3_5")],
            ])
        )
        update_user(uid, research_awaiting=f"3_open:{RESEARCH_OPEN_Q_DAY3_OK}")

    elif day == 7:
        thought = g(user["gender"], "подумал", "подумала")
        await app.bot.send_message(
            chat_id=uid,
            text=(
                f"🔬 *{name}, ты с ботом уже неделю!*\n\n"
                f"Был ли момент когда {thought} «о, это работает»?"
            ),
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("✅ Да, был такой момент", callback_data="research_7_yes")],
                [InlineKeyboardButton(personalize("🤔 Не уверен(а)", user["gender"]), callback_data="research_7_maybe")],
                [InlineKeyboardButton("❌ Нет пока", callback_data="research_7_no")],
            ])
        )

    elif day == 14:
        await app.bot.send_message(
            chat_id=uid,
            text=(
                f"🔬 *{name}, 2 недели вместе!*\n\n"
                f"Насколько вероятно что порекомендуешь бота другу с СДВГ?\n\n"
                f"0 — точно не порекомендую, 10 — точно порекомендую"
            ),
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(str(i), callback_data=f"research_14_{i}") for i in range(0, 6)],
                [InlineKeyboardButton(str(i), callback_data=f"research_14_{i}") for i in range(6, 11)],
            ])
        )
        update_user(uid, research_awaiting=f"14_open:{RESEARCH_OPEN_Q_DAY14}")

    elif day == 30:
        await app.bot.send_message(
            chat_id=uid,
            text=(
                f"🔬 *{name}, месяц с ботом!*\n\n"
                f"Если бот перестанет работать — как ты к этому отнесёшься?"
            ),
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("😢 Очень расстроюсь", callback_data="research_30_sad")],
                [InlineKeyboardButton("😕 Немного расстроюсь", callback_data="research_30_meh")],
                [InlineKeyboardButton("😐 Всё равно", callback_data="research_30_nope")],
                [InlineKeyboardButton(personalize("😅 Даже рад(а)", user["gender"]), callback_data="research_30_glad")],
            ])
        )
    else:
        return  # неизвестный день — ничего не отправили, помечать нечего

    # Помечаем как отправленный только теперь, когда сообщение реально ушло —
    # раньше это делалось ДО отправки, и временный сбой Telegram навсегда
    # хоронил этот research-вопрос без единой попытки повтора (та же
    # ошибка, что уже чинили для утро/день/вечер/+2ч/weekly_report).
    done_list = [x for x in research_done.split(",") if x]
    if str(day) not in done_list:
        done_list.append(str(day))
        update_user(uid, research_done=",".join(done_list))

async def research_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    uid = q.from_user.id
    parts = q.data.split("_")  # research_DAY_VALUE
    day = int(parts[1])
    value = "_".join(parts[2:])
    gender = get_user(uid)["gender"]

    LABELS = {
        "yes": "Да, был момент", "maybe": "Не уверен(а)", "no": "Нет пока",
        "sad": "Очень расстроюсь", "meh": "Немного расстроюсь",
        "nope": "Всё равно", "glad": "Даже рад(а)",
    }
    answer = personalize(LABELS.get(value, value), gender)
    save_research(uid, day, f"day{day}_rating", answer)

    # Переслать ответ администратору
    user = get_user(uid)
    low_rating = value in ("1", "2")  # флаг низкой оценки
    if NOTIFY_USER_ID:
        try:
            alert = "⚠️ *НИЗКАЯ ОЦЕНКА — нужна связь!*\n\n" if low_rating else ""
            contact = f"\n🔗 Telegram ID: `{uid}`" if low_rating else ""
            q_text = RESEARCH_QUESTION_LABELS.get(f"day{day}_rating", "")
            await q.message.bot.send_message(
                NOTIFY_USER_ID,
                f"{alert}🔬 *Исследование день {day} от {md_escape(user['name']) or uid}:*\n\n"
                f"_{q_text}_\nОценка: {answer}{contact}",
                parse_mode="Markdown"
            )
        except Exception as e:
            print(f"Не удалось переслать рейтинг: {e}")

    # Отмечаем день как пройденный
    user = get_user(uid)
    done = user.get("research_done") or ""
    done_list = [x for x in done.split(",") if x]
    if str(day) not in done_list:
        done_list.append(str(day))
    update_user(uid, research_done=",".join(done_list))

    if day == 3:
        if low_rating:
            open_q = RESEARCH_OPEN_Q_DAY3_LOW
            followup = (
                f"Записал. Оценка {value}/5 — буду разбираться.\n\n"
                f"Расскажи подробнее текстом:\n\n"
                f"*{open_q}* Любая деталь поможет."
            )
        else:
            open_q = RESEARCH_OPEN_Q_DAY3_OK
            followup = (
                f"Спасибо! Оценка {value}/5 записана.\n\n"
                f"И ещё один вопрос — ответь текстом:\n\n"
                f"*{open_q}*"
            )
        update_user(uid, research_awaiting=f"3_open:{open_q}")
        await q.message.reply_text(followup, parse_mode="Markdown")
    elif day == 7:
        await q.message.reply_text(
            "Записал! Спасибо за честный ответ 🙏\n\nПродолжай — впереди ещё много интересного.",
            reply_markup=menu_button_kb()
        )
        update_user(uid, research_awaiting=f"7_open:{RESEARCH_OPEN_Q_DAY7}")
        await q.message.reply_text(
            f"*И ещё:* {RESEARCH_OPEN_Q_DAY7}\n\nОтветь текстом.",
            parse_mode="Markdown"
        )
    elif day == 14:
        update_user(uid, research_awaiting=f"14_open:{RESEARCH_OPEN_Q_DAY14}")
        await q.message.reply_text(
            f"NPS {value} — записал!\n\n"
            f"*И последнее — ответь текстом:*\n\n{RESEARCH_OPEN_Q_DAY14}",
            parse_mode="Markdown"
        )
    elif day == 30:
        await q.message.reply_text(
            "Спасибо! Это очень важный для меня ответ 🙏\n\nБот продолжает работать — до встречи завтра.",
            reply_markup=menu_button_kb()
        )


