async def guide_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    await send_guide_section(q.message, "what")

async def guide_section(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query; await q.answer()
    section_id = q.data.replace("guide_", "")
    await send_guide_section(q.message, section_id)

async def send_guide_section(message, section_id):
    section = GUIDE_SECTIONS.get(section_id)
    if not section: return

    # Build navigation buttons
    buttons = []
    # Section dots navigation
    dot_row = []
    for key in GUIDE_SECTIONS:
        if key == section_id:
            dot_row.append(InlineKeyboardButton("●", callback_data=f"guide_{key}"))
        else:
            dot_row.append(InlineKeyboardButton("○", callback_data=f"guide_{key}"))
    buttons.append(dot_row)

    # Next button
    if section["next"]:
        next_title = GUIDE_SECTIONS[section["next"]]["title"]
        buttons.append([InlineKeyboardButton(f"Далее: {next_title} →", callback_data=f"guide_{section['next']}")])

    buttons.append([InlineKeyboardButton("◀️ Меню", callback_data="go_menu")])

    await message.reply_text(
        section["text"],
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup(buttons)
    )


async def check_notifications(app):
    """Каждую минуту — уведомления для всех пользователей у кого они включены."""
    global _last_heartbeat
    _last_heartbeat = time.monotonic()
    try:
        users = get_all_notif_users()

        for user in users:
            uid = user["user_id"]
            # Каждый пользователь — своя таймзона
            tz = get_user_tz(user)
            now_dt = datetime.now(tz)
            now = now_dt.strftime("%H:%M")
            is_sunday = now_dt.weekday() == 6
            try:
                day_key = now_dt.strftime("%Y-%m-%d")

                # Утро/день/вечер и +2ч напоминание отмечаются как отправленные
                # в БД, и триггер — "время уже наступило и сегодня ещё не
                # отправлено", а не "ровно эта минута". Иначе один пропущенный
                # тик (рестарт от вотчдога, деплой ровно в нужную минуту)
                # молча хоронит уведомление на весь день — это реально
                # случалось.
                # notif_enabled — общий тумблер конкретно для этих 3x/день
                # уведомлений; маячок/фокус-таймер/resume-check ниже от него
                # не зависят — у них своё собственное включение.
                notif_master_on = int(user.get("notif_enabled") or 0)
                if (notif_master_on and now >= user.get("notif_morning", "09:00") and int(user.get("notif_morning_on") or 1)
                        and user.get("morning_sent_date") != day_key):
                    # Помечаем "отправлено" только после реального успеха — иначе
                    # временный сбой (таймаут телеграма, юзер заблокировал бота)
                    # навсегда съедает уведомление на весь день без единой попытки.
                    if await morning_notification(app, uid):
                        update_user(uid, morning_sent_date=day_key)

                # Воскресный отчёт — независимое условие, не вложенное в блок
                # утреннего уведомления: раньше он делил с ним внешний if, и
                # получал ровно одну попытку в тот же тик, что и morning —
                # если сама эта попытка проваливалась, следующий тик уже не
                # заходил внутрь (morning_sent_date к тому моменту чаще всего
                # уже проставлен), и weekly_report больше не пересматривался
                # до понедельника. Заодно раньше зависел от notif_morning_on,
                # хотя это разные, независимо переключаемые уведомления.
                if (notif_master_on and is_sunday and now >= user.get("notif_morning", "09:00")
                        and user.get("weekly_report_sent_date") != day_key):
                    if await weekly_report(app, uid):
                        update_user(uid, weekly_report_sent_date=day_key)

                if (notif_master_on and now >= user.get("notif_midday", "13:00") and int(user.get("notif_midday_on") or 1)
                        and user.get("midday_sent_date") != day_key):
                    if await midday_notification(app, uid):
                        update_user(uid, midday_sent_date=day_key)

                if (notif_master_on and now >= user.get("notif_evening", "21:00") and int(user.get("notif_evening_on") or 1)
                        and user.get("evening_sent_date") != day_key):
                    if await evening_notification(app, uid):
                        update_user(uid, evening_sent_date=day_key)

                # Напоминание если пропустил утро (+2 часа) — та же логика
                # "время прошло и сегодня ещё не отправлено", что и для
                # утро/день/вечер выше, а не точное совпадение минуты.
                try:
                    mh, mm = map(int, user.get("notif_morning", "09:00").split(":"))
                    reminder_time = now_dt.replace(hour=mh, minute=mm, second=0, microsecond=0) + timedelta(hours=2)
                    # Если пользователь уже внутри утреннего диалога (просто ещё не
                    # дошёл до задач) — не шлём это напоминание. Его кнопка "Заполнить
                    # утро" ведёт на entry point с allow_reentry=True и перезапускает
                    # morning_start с нуля, стирая уже введённый прогресс (реальный баг).
                    morning_conv_active = _morning_conv is not None and (uid, uid) in _morning_conv._conversations
                    if (notif_master_on and now >= reminder_time.strftime("%H:%M") and int(user.get("notif_morning_on") or 1)
                            and user.get("morning_reminder_sent_date") != day_key
                            and not get_diary(uid, "morning", day_key)
                            and not morning_conv_active):
                        # Как и остальные уведомления в этом тике — помечаем
                        # "отправлено" только после реального успеха, а не до
                        # (раньше было наоборот: временный сбой отправки навсегда
                        # съедал это напоминание на весь день без единой попытки).
                        await app.bot.send_message(
                            chat_id=uid,
                            text="☀️ *Утро ещё не закрыто*\n\nЕщё не поздно поставить задачи на день — займёт 2 минуты.",
                            parse_mode="Markdown",
                            reply_markup=InlineKeyboardMarkup([[
                                InlineKeyboardButton("☀️ Заполнить утро", callback_data="go_morning")
                            ]])
                        )
                        update_user(uid, morning_reminder_sent_date=day_key)
                except Exception:
                    pass

                # Маячок — два независимых блока: задачи и навыки
                await send_task_beacon(app, user)
                await send_skill_beacon(app, user)

                # Разовое напоминание "пора начинать" — время задаётся
                # утром, см. morning_task_offer_yes / send_work_start_reminder
                await send_work_start_reminder(app, user)

                # Свои напоминания (⏰ Напоминания) — разбираются ИИ из
                # свободного текста, см. parse_reminder_request
                await send_due_reminders(app, user, now_dt)

                # Повторная проверка после "Отдыхаю 10-15 мин" — хранится в БД
                # (не в памяти планировщика), чтобы рестарт процесса её не терял
                due_raw = user.get("resume_check_due") or ""
                if due_raw:
                    try:
                        due_dt = datetime.fromisoformat(due_raw)
                        if now_dt >= due_dt:
                            # user — снапшот с начала тика; между ним и этой
                            # строкой прошло время (await на других
                            # уведомлениях того же пользователя выше). Если
                            # человек уже сам нажал "Отдыхаю" ещё раз и
                            # запланировал новую проверку — сверяем со
                            # свежим значением из БД, иначе затираем её
                            # пустой строкой прямо под носом (тот же баг
                            # класс, что чинили в send_focus_end).
                            fresh_due = get_user(uid).get("resume_check_due") or ""
                            if fresh_due == due_raw and await send_resume_check(app.bot, uid):
                                update_user(uid, resume_check_due="")
                    except Exception as e:
                        print(f"Ошибка resume_check_due uid={uid}: {e}")

                # Исследовательские вопросы — тот же общий тумблер notif_enabled,
                # что и утро/день/вечер: "выключить всё" должно выключать и их.
                if notif_master_on:
                    try:
                        created_at = user.get("created_at") or now_dt.date().isoformat()
                        days_since = (now_dt.date() - date.fromisoformat(str(created_at)[:10])).days
                        done_days = [x for x in (user.get("research_done") or "").split(",") if x]
                        for milestone in [3, 7, 14, 30]:
                            if days_since >= milestone and str(milestone) not in done_days:
                                if 10 <= now_dt.hour <= 12:
                                    await send_research_question(app, uid, milestone)
                                break
                    except Exception as e:
                        print(f"Ошибка research uid={uid}: {e}")

                # Фокус-таймер
                if str(user.get("focus_active", "0")) == "1" and user.get("focus_end_time"):
                    try:
                        end_dt = datetime.fromisoformat(user["focus_end_time"]).astimezone(tz)
                        if now_dt >= end_dt:
                            await send_focus_end(app, uid, int(user.get("focus_duration", 25) or 25), user["focus_end_time"])
                    except Exception as e:
                        print(f"Ошибка focus uid={uid}: {e}")

            except Exception as e:
                print(f"Ошибка check_notifications uid={uid}: {e}")

    except Exception as e:
        print(f"Ошибка check_notifications: {e}")


# ── WATCHDOG ───────────────────────────────────────────────────────────────
# check_notifications обновляет heartbeat каждую минуту через APScheduler,
# который работает в том же asyncio event loop, что и long-polling бота.
# Если event loop зависнет (напр. сетевая ошибка Telegram оставила зависший
# запрос без таймаута — так уведомления не приходили 4 дня в июле 2026),
# APScheduler тоже перестаёт тикать и heartbeat не обновляется.
# Watchdog живёт в отдельном OS-потоке и не зависит от event loop, поэтому
# может обнаружить зависание и убить процесс — Railway (restartPolicyType
# ON_FAILURE) поднимет контейнер заново.
_last_heartbeat = time.monotonic()
HEARTBEAT_TIMEOUT_SEC = 5 * 60

def _watchdog_loop():
    while True:
        time.sleep(30)
        stale = time.monotonic() - _last_heartbeat
        if stale > HEARTBEAT_TIMEOUT_SEC:
            print(f"⚠️ Watchdog: event loop завис ({stale:.0f}с без heartbeat) — перезапуск процесса", flush=True)
            os._exit(1)

async def on_error(update, ctx: ContextTypes.DEFAULT_TYPE):
    print(f"⚠️ Необработанная ошибка: {ctx.error}", flush=True)


async def admin_feedback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    if NOTIFY_USER_ID and uid != NOTIFY_USER_ID:
        await update.message.reply_text(f"⛔ Нет доступа.\n\nТвой ID: `{uid}`", parse_mode="Markdown")
        return
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute("SELECT user_id, text, created FROM feedback ORDER BY created DESC LIMIT 50").fetchall()
    conn.close()
    if not rows:
        await update.message.reply_text("Фидбэков пока нет.")
        return
    lines = []
    for user_id, text, created in rows:
        user = get_user(user_id)
        name = md_escape(user["name"]) if user and user["name"] else str(user_id)
        date_str = created[:10] if created else "?"
        lines.append(f"*{name}* ({date_str}):\n{md_escape(text)}")
    msg = "\n\n─────\n\n".join(lines)
    # Telegram limit 4096 chars per message
    for i in range(0, len(msg), 4000):
        await update.message.reply_text(msg[i:i+4000], parse_mode="Markdown")


RESEARCH_MILESTONES = [3, 7, 14, 30]
RESEARCH_TEXT_FOLLOWUP_DAYS = {3, 7, 14}  # у дня 30 нет открытого текстового вопроса

async def admin_research(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    if NOTIFY_USER_ID and uid != NOTIFY_USER_ID:
        await update.message.reply_text(f"⛔ Нет доступа.\n\nТвой ID: `{uid}`", parse_mode="Markdown")
        return
    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute("SELECT user_id, day, question, answer, created FROM research ORDER BY created DESC LIMIT 100").fetchall()
    answered = conn.execute("SELECT DISTINCT user_id, question FROM research").fetchall()
    users_with_research = conn.execute(
        "SELECT user_id, name, research_done FROM users WHERE research_done IS NOT NULL AND research_done != ''"
    ).fetchall()
    conn.close()

    lines = []
    for user_id, day, question, answer, created in rows:
        user = get_user(user_id)
        name = md_escape(user["name"]) if user and user["name"] else str(user_id)
        date_str = created[:10] if created else "?"
        q_text = RESEARCH_QUESTION_LABELS.get(question, question)
        lines.append(f"*{name}* · день {day} ({date_str}):\n_{q_text}_\n{md_escape(answer)}")

    # Какие вопросы отправили, но человек так и не ответил — иначе это молча
    # теряется: research_done проставляется в момент ОТПРАВКИ, а не ответа.
    answered_set = set(answered)
    skipped_lines = []
    for user_id, name, research_done in users_with_research:
        label = md_escape(name) if name else str(user_id)
        for day in (int(d) for d in research_done.split(",") if d):
            rating_key = f"day{day}_rating"
            if (user_id, rating_key) not in answered_set:
                skipped_lines.append(f"*{label}* · день {day}: {RESEARCH_QUESTION_LABELS.get(rating_key, rating_key)}")
                continue  # без ответа на рейтинг открытый вопрос ещё не задавался
            if day in RESEARCH_TEXT_FOLLOWUP_DAYS:
                text_key = f"day{day}_text"
                if (user_id, text_key) not in answered_set:
                    skipped_lines.append(f"*{label}* · день {day}: {RESEARCH_QUESTION_LABELS.get(text_key, text_key)}")

    if not lines and not skipped_lines:
        await update.message.reply_text("Ответов на исследования пока нет.")
        return

    msg = "\n\n─────\n\n".join(lines) if lines else "_Ответов пока нет._"
    if skipped_lines:
        msg += "\n\n─────\n\n⏳ *Спросили, но не ответили:*\n" + "\n".join(skipped_lines)
    for i in range(0, len(msg), 4000):
        await update.message.reply_text(msg[i:i+4000], parse_mode="Markdown")


async def admin_stats(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    if NOTIFY_USER_ID and uid != NOTIFY_USER_ID:
        await update.message.reply_text(
            f"⛔ Нет доступа.\n\nТвой ID: `{uid}`",
            parse_mode="Markdown"
        )
        return
    try:
        conn = sqlite3.connect(DB_PATH)
        cur = conn.cursor()

        total = cur.execute("SELECT COUNT(*) FROM users WHERE name != ''").fetchone()[0]
        week_ago  = (date.today() - timedelta(days=7)).isoformat()
        month_ago = (date.today() - timedelta(days=30)).isoformat()
        active7  = cur.execute("SELECT COUNT(DISTINCT user_id) FROM diary WHERE date >= ?", (week_ago,)).fetchone()[0]
        active30 = cur.execute("SELECT COUNT(DISTINCT user_id) FROM diary WHERE date >= ?", (month_ago,)).fetchone()[0]

        # Пол
        males   = cur.execute("SELECT COUNT(*) FROM users WHERE gender='M' AND name!=''").fetchone()[0]
        females = cur.execute("SELECT COUNT(*) FROM users WHERE gender='F' AND name!=''").fetchone()[0]
        nonbin  = cur.execute("SELECT COUNT(*) FROM users WHERE gender='N' AND name!=''").fetchone()[0]

        # Города
        cities = cur.execute(
            "SELECT city, COUNT(*) as cnt FROM users WHERE city!='' AND city IS NOT NULL GROUP BY city ORDER BY cnt DESC LIMIT 10"
        ).fetchall()

        checkins = cur.execute(
            "SELECT block, COUNT(*) FROM diary GROUP BY block"
        ).fetchall()
        block_map = {r[0]: r[1] for r in checkins}

        # Доступ/подписка
        conn.row_factory = sqlite3.Row
        cur2 = conn.cursor()
        access_rows = cur2.execute("SELECT * FROM users WHERE name != ''").fetchall()
        access_counts = {"trial": 0, "subscribed": 0, "expired": 0}
        for r in access_rows:
            access_counts[get_access_status(dict(r))] += 1
        promo_redemptions_total = cur.execute("SELECT COUNT(*) FROM promo_redemptions").fetchone()[0]
        paid_users = cur.execute("SELECT COUNT(DISTINCT user_id) FROM payments").fetchone()[0]
        stars_total = cur.execute("SELECT COALESCE(SUM(stars), 0) FROM payments").fetchone()[0]

        # Research summary
        r3_ratings  = cur.execute("SELECT answer FROM research WHERE day=3 AND question='day3_rating'").fetchall()
        r14_nps     = cur.execute("SELECT answer FROM research WHERE day=14 AND question='day14_rating'").fetchall()
        r30_pmf     = cur.execute("SELECT answer FROM research WHERE day=30 AND question='day30_rating'").fetchall()
        r3_texts    = cur.execute("SELECT answer FROM research WHERE day=3 AND question='day3_text'").fetchall()
        r7_texts    = cur.execute("SELECT answer FROM research WHERE day=7 AND question='day7_text'").fetchall()
        r14_texts   = cur.execute("SELECT answer FROM research WHERE day=14 AND question='day14_text'").fetchall()
        conn.close()

        # Avg day-3 rating
        d3_avg = ""
        if r3_ratings:
            nums = [int(r[0]) for r in r3_ratings if r[0].isdigit()]
            if nums: d3_avg = f"  Оценка день 3: *{sum(nums)/len(nums):.1f}/5* ({len(nums)} отв.)\n"

        # NPS
        nps_str = ""
        if r14_nps:
            scores = [int(r[0]) for r in r14_nps if r[0].isdigit()]
            if scores:
                promoters  = sum(1 for s in scores if s >= 9)
                detractors = sum(1 for s in scores if s <= 6)
                nps = round((promoters - detractors) / len(scores) * 100)
                nps_str = f"  NPS (день 14): *{nps}* ({len(scores)} отв.)\n"

        # PMF
        pmf_str = ""
        if r30_pmf:
            sad_count = sum(1 for r in r30_pmf if "Очень" in r[0])
            pmf_pct = round(sad_count / len(r30_pmf) * 100) if r30_pmf else 0
            pmf_str = f"  PMF «очень расстроюсь» (день 30): *{pmf_pct}%* ({len(r30_pmf)} отв.)\n"

        # Open answers
        def fmt_answers(rows, label):
            if not rows: return ""
            out = f"\n*{label}:*\n"
            for r in rows[-3:]:
                out += f"— _{r[0]}_\n"
            return out

        cities_str = "\n".join(f"  {r[0]}: {r[1]}" for r in cities) if cities else "  —"

        text = (
            f"📊 *Статистика бота*\n\n"
            f"👤 Всего пользователей: *{total}*\n"
            f"  👨 Мужчин: {males} · 👩 Женщин: {females}" + (f" · 🏳️‍🌈 Другое: {nonbin}" if nonbin else "") + "\n"
            f"📅 Активны за 7 дней: *{active7}*\n"
            f"📅 Активны за 30 дней: *{active30}*\n\n"
            f"💎 *Доступ:* 🎁 Пробный: {access_counts['trial']} · ✅ Подписка: {access_counts['subscribed']} · "
            f"⌛ Истёк: {access_counts['expired']} · 🎟 Промокодов активировано: {promo_redemptions_total}\n"
            f"💳 *Оплатили:* {paid_users} чел. · ⭐ Всего получено: {stars_total} Stars\n\n"
            f"🌍 *Города:*\n{cities_str}\n\n"
            f"📋 *Чекины:*\n"
            f"  ☀️ Утро: {block_map.get('morning',0)}\n"
            f"  ☕ День: {block_map.get('midday',0)}\n"
            f"  🌙 Вечер: {block_map.get('evening',0)}\n\n"
            f"🔬 *Исследование:*\n"
            f"{d3_avg}{nps_str}{pmf_str}"
            f"{fmt_answers(r3_texts, 'Что полезно (день 3)')}"
            f"{fmt_answers(r7_texts, 'Что мешало (день 7)')}"
            f"{fmt_answers(r14_texts, 'Что упростить (день 14)')}"
        )
        await update.message.reply_text(text, parse_mode="Markdown")
    except Exception as e:
        await update.message.reply_text(f"❌ Ошибка: `{e}`", parse_mode="Markdown")


async def admin_users(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    if NOTIFY_USER_ID and uid != NOTIFY_USER_ID:
        await update.message.reply_text(
            f"⛔ Нет доступа.\n\nТвой ID: `{uid}`",
            parse_mode="Markdown"
        )
        return
    try:
        conn = sqlite3.connect(DB_PATH)
        cur = conn.cursor()
        rows = cur.execute(
            "SELECT user_id, name, gender FROM users WHERE name != ''"
        ).fetchall()
        conn.close()

        if not rows:
            await update.message.reply_text("Пользователей пока нет.")
            return

        # Кнопка на каждого пользователя — нажать чтобы написать; вторая —
        # выдать доступ на 30 дней без промокода, для конкретного человека.
        buttons = []
        for uid_u, name, gender in rows:
            g = {"M": "👨", "F": "👩", "N": "🏳️‍🌈"}.get(gender, "")
            buttons.append([
                InlineKeyboardButton(f"{g} {name}", callback_data=f"admin_msg_{uid_u}"),
                InlineKeyboardButton("🎁 +30", callback_data=f"grant30_{uid_u}"),
            ])

        await update.message.reply_text(
            f"👥 *Пользователи ({len(rows)})*\n\nИмя — написать · 🎁 +30 — выдать 30 дней доступа без промокода:",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup(buttons)
        )
    except Exception as e:
        await update.message.reply_text(f"❌ Ошибка: `{e}`", parse_mode="Markdown")


async def admin_msg_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Нажата кнопка с именем пользователя — спрашиваем текст сообщения."""
    q = update.callback_query; await q.answer()
    admin_uid = q.from_user.id
    if NOTIFY_USER_ID and admin_uid != NOTIFY_USER_ID:
        return
    clear_awaiting_flags(ctx, update)
    target_id = int(q.data.split("_")[2])
    # Найдём имя
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute("SELECT name FROM users WHERE user_id=?", (target_id,)).fetchone()
    conn.close()
    name = row[0] if row else str(target_id)
    ctx.user_data["admin_msg_target"] = target_id
    ctx.user_data["admin_msg_name"] = name
    await q.message.reply_text(
        f"✉️ Пишешь *{md_escape(name)}*.\n\nВведи текст сообщения:",
        parse_mode="Markdown"
    )


async def admin_send(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    if NOTIFY_USER_ID and uid != NOTIFY_USER_ID:
        await update.message.reply_text("⛔ Нет доступа.", parse_mode="Markdown")
        return
    args = ctx.args
    if not args or len(args) < 2:
        await update.message.reply_text(
            "Использование: `/send <user_id> <текст>`\n\nПример:\n`/send 123456789 Привет, увидел твою оценку`",
            parse_mode="Markdown"
        )
        return
    try:
        target_id = int(args[0])
        text = " ".join(args[1:])
        await ctx.bot.send_message(target_id, text)
        await update.message.reply_text(f"✅ Отправлено пользователю `{target_id}`", parse_mode="Markdown")
    except ValueError:
        await update.message.reply_text("❌ Неверный ID — должно быть число.")
    except Exception as e:
        await update.message.reply_text(f"❌ Не удалось отправить: `{e}`", parse_mode="Markdown")

async def admin_broadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Разослать сообщение всем зарегистрированным пользователям.

    Текст рассылки берётся из сообщения, на которое отвечаешь (reply) — так
    сохраняются переносы строк и Markdown-разметка, которые /broadcast текст
    аргументами команды потерял бы (Telegram схлопывает их в одну строку).
    Можно и одной строкой: /broadcast текст — тогда без переносов."""
    uid = update.effective_user.id
    if NOTIFY_USER_ID and uid != NOTIFY_USER_ID:
        await update.message.reply_text("⛔ Нет доступа.")
        return
    reply = update.message.reply_to_message
    text = reply.text if (reply and reply.text) else " ".join(ctx.args)
    if not text:
        await update.message.reply_text(
            "Использование: напиши текст рассылки отдельным сообщением боту, "
            "затем ответь на него командой /broadcast (сохранит форматирование "
            "и переносы строк). Либо `/broadcast текст` одной строкой.",
            parse_mode="Markdown"
        )
        return

    conn = sqlite3.connect(DB_PATH)
    rows = conn.execute("SELECT user_id FROM users WHERE name != ''").fetchall()
    conn.close()

    sent, failed = 0, 0
    for (target_id,) in rows:
        try:
            await ctx.bot.send_message(target_id, text, parse_mode="Markdown")
            sent += 1
        except Exception as e:
            failed += 1
            print(f"Ошибка рассылки uid={target_id}: {e}")
        await asyncio.sleep(0.05)  # не упереться в лимиты Telegram на большой базе

    hint = "\n\n_Если 0 доставлено — возможно, проблема в Markdown-разметке текста._" if sent == 0 and failed else ""
    await update.message.reply_text(
        f"✅ Разослано: {sent}. Не удалось: {failed}.{hint}",
        parse_mode="Markdown"
    )


def main():
    init_db()
    persistence = PicklePersistence(filepath=PERSISTENCE_PATH)
    app = (
        Application.builder()
        .token(BOT_TOKEN)
        .persistence(persistence)
        .connect_timeout(30)
        .read_timeout(30)
        .write_timeout(30)
        .pool_timeout(30)
        .get_updates_connect_timeout(30)
        .get_updates_read_timeout(40)
        .get_updates_write_timeout(30)
        .get_updates_pool_timeout(30)
        .build()
    )
    app.add_error_handler(on_error)

    # Онбординг
    onboard_conv = ConversationHandler(
        entry_points=[CommandHandler("start", start)],
        states={
            ONBOARD_NAME:   [MessageHandler(filters.TEXT & ~filters.COMMAND, got_name)],
            ONBOARD_GENDER: [CallbackQueryHandler(got_gender, pattern="^gender_")],
        },
        fallbacks=[CommandHandler("start", start)],
        allow_reentry=True,
        conversation_timeout=CONV_TIMEOUT_SHORT,
        persistent=True, name="onboard_conv",
    )

    # Утренний flow (порядок: разминка → ритуал → задачи)
    morning_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(morning_start, pattern="^go_morning$")],
        states={
            M_EXERCISE: [
                CallbackQueryHandler(warmup_go,      pattern="^warmup_go$"),
                CallbackQueryHandler(warmup_done,    pattern="^warmup_done$"),
                CallbackQueryHandler(skip_warmup,    pattern="^skip_warmup$"),
                CallbackQueryHandler(morning_quick,  pattern="^morning_quick$"),
            ],
            # Сначала мягкий ритуал
            M_WRITING:  [MessageHandler(filters.TEXT & ~filters.COMMAND, got_writing),    CallbackQueryHandler(skip_m_writing,  pattern="^skip_m_writing$")],
            M_GRATITUDE:[MessageHandler(filters.TEXT & ~filters.COMMAND, got_gratitude),  CallbackQueryHandler(skip_m_gratitude,pattern="^skip_m_gratitude$")],
            M_CHILD:    [MessageHandler(filters.TEXT & ~filters.COMMAND, got_child),      CallbackQueryHandler(skip_m_child,    pattern="^skip_m_child$")],
            # Задачи A/B/C больше не встроенный шаг — см. комментарий у
            # RESUME_FIELDS. M_FOCUS/M_B1/M_B2/M_C1/M_C2/M_C3 намеренно не
            # зарегистрированы здесь, поэтому недостижимы.
        },
        fallbacks=[CommandHandler("start", start)],
        allow_reentry=True,
        conversation_timeout=CONV_TIMEOUT_LONG,
        persistent=True, name="morning_conv",
    )

    # Вечерний flow
    evening_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(evening_start, pattern="^go_evening$")],
        states={
            E_TASKS_DONE:[CallbackQueryHandler(tasks_done_finish, pattern="^td_done$"), CallbackQueryHandler(toggle_task_done, pattern="^td_")],
            E_ACH:       [MessageHandler(filters.TEXT & ~filters.COMMAND, got_e_ach),      CallbackQueryHandler(skip_e_ach,      pattern="^skip_e_ach$")],
            E_PRAISE:    [MessageHandler(filters.TEXT & ~filters.COMMAND, got_e_praise),   CallbackQueryHandler(skip_e_praise,   pattern="^skip_e_praise$")],
            E_HIGHLIGHTS:[MessageHandler(filters.TEXT & ~filters.COMMAND, got_e_highlights),CallbackQueryHandler(skip_e_highlights,pattern="^skip_e_highlights$")],
            E_SELFCARE:  [CallbackQueryHandler(selfcare_done,  pattern="^sc_done$"), CallbackQueryHandler(toggle_selfcare, pattern="^sc_")],
            E_ENERGY:    [CallbackQueryHandler(got_energy, pattern="^energy_[1-5]$")],
            E_A:         [MessageHandler(filters.TEXT & ~filters.COMMAND, got_e_a),        CallbackQueryHandler(skip_e_a,        pattern="^skip_e_a$"),
                          CallbackQueryHandler(skip_all_goals, pattern="^skip_all_goals$")],
            E_B1:        [MessageHandler(filters.TEXT & ~filters.COMMAND, got_e_b1),       CallbackQueryHandler(skip_e_b1,       pattern="^skip_e_b1$")],
            E_B2:        [MessageHandler(filters.TEXT & ~filters.COMMAND, got_e_b2),       CallbackQueryHandler(skip_e_b2,       pattern="^skip_e_b2$")],
            E_C1:        [MessageHandler(filters.TEXT & ~filters.COMMAND, got_e_c1),       CallbackQueryHandler(skip_e_c_all,    pattern="^skip_e_c_all$")],
            E_C2:        [MessageHandler(filters.TEXT & ~filters.COMMAND, got_e_c2),       CallbackQueryHandler(skip_e_c_all,    pattern="^skip_e_c_all$")],
            E_C3:        [MessageHandler(filters.TEXT & ~filters.COMMAND, got_e_c3),       CallbackQueryHandler(skip_e_c_all,    pattern="^skip_e_c_all$")],
        },
        fallbacks=[CommandHandler("start", start)],
        allow_reentry=True,
        conversation_timeout=CONV_TIMEOUT_LONG,
        persistent=True, name="evening_conv",
    )

    app.add_handler(CommandHandler("admin", admin_stats), group=-1)
    app.add_handler(CommandHandler("feedback", admin_feedback), group=-1)
    app.add_handler(CommandHandler("research", admin_research), group=-1)
    app.add_handler(CommandHandler("users", admin_users), group=-1)
    app.add_handler(CommandHandler("send", admin_send), group=-1)
    app.add_handler(CommandHandler("broadcast", admin_broadcast), group=-1)
    app.add_handler(CallbackQueryHandler(admin_msg_start, pattern="^admin_msg_"), group=-1)
    app.add_handler(CommandHandler("newpromo", newpromo_command), group=-1)
    app.add_handler(CommandHandler("blogger", blogger_command), group=-1)
    app.add_handler(CommandHandler("promocodes", promocodes_command), group=-1)
    app.add_handler(CommandHandler("grant", grant_command), group=-1)
    app.add_handler(CallbackQueryHandler(grant30_callback, pattern="^grant30_"), group=-1)
    app.add_handler(TypeHandler(Update, dedupe_updates), group=-3)
    app.add_handler(TypeHandler(Update, access_gate), group=-2)
    app.add_handler(onboard_conv)
    global _morning_conv, _evening_conv
    _morning_conv = morning_conv
    _evening_conv = evening_conv
    app.add_handler(morning_conv)
    app.add_handler(evening_conv)
    app.add_handler(CallbackQueryHandler(onboard_done,       pattern="^onboard_done$"))
    app.add_handler(CallbackQueryHandler(onboard_explain_yes, pattern="^onboard_explain_yes$"))
    app.add_handler(CallbackQueryHandler(onboard_explain_no,  pattern="^onboard_explain_no$"))
    app.add_handler(CallbackQueryHandler(onboard_explain_late, pattern="^onboard_explain_late$"))
    app.add_handler(CallbackQueryHandler(onboard_explain_step, pattern=r"^expl_\d+_\w+$"))
    # Fallback для кнопок пола — на случай если ConversationHandler потерял состояние при перезапуске
    app.add_handler(CallbackQueryHandler(got_gender, pattern="^gender_[MFN]$"))
    app.add_handler(CallbackQueryHandler(problems_done,       pattern="^prob_done$"))
    app.add_handler(CallbackQueryHandler(toggle_problem,      pattern="^pt_"))
    app.add_handler(CallbackQueryHandler(problem_group_next,  pattern="^pn_"))
    app.add_handler(CallbackQueryHandler(onboard_notif_on,   pattern="^onboard_notif_on$"))
    app.add_handler(CallbackQueryHandler(onboard_notif_skip, pattern="^onboard_notif_skip$"))
